      noImp++;
    }

    var eliteN = Math.max(2, Math.min(7, Math.floor(genStats.length * 0.35)));
    var elites = [];
    var e;
    for (e = 0; e < eliteN && e < genStats.length; e++) {
      if (!genStats[e].st.invalid) elites.push(genStats[e]);
    }
    if (elites.length < 2) {
      elites = [];
      for (e = 0; e < Math.min(eliteN, genStats.length); e++) elites.push(genStats[e]);
    }

    var newMean = [];
    var newSigma = [];
    for (j = 0; j < KI.length; j++) {
      var wsum = 0;
      var m = 0;
      var r;
      for (r = 0; r < elites.length; r++) {
        var w = 1 / (r + 1);
        m += w * elites[r].v[j];
        wsum += w;
      }
      m /= (wsum || 1);
      var vsum = 0;
      var w2 = 0;
      for (r = 0; r < elites.length; r++) {
        var ww = 1 / (r + 1);
        var dv = elites[r].v[j] - m;
        vsum += ww * dv * dv;
        w2 += ww;
      }
      var sd = Math.sqrt(Math.max(0, vsum / (w2 || 1)));
      newMean[j] = m;
      newSigma[j] = sd;
    }

    for (j = 0; j < KI.length; j++) {
      var lo2 = KI[j][1], hi2 = KI[j][2];
      meanVec[j] = clamp(0.35 * meanVec[j] + 0.65 * newMean[j], lo2, hi2);
      var sigFloor = Math.max(0.005, (hi2 - lo2) * 0.0025);
      var sigCeil = (hi2 - lo2) * 0.80;
      var sN = 0.35 * sigmaVec[j] + 0.75 * newSigma[j] + 0.015 * (hi2 - lo2);
      if (noImp >= 2) sN += 0.08 * (hi2 - lo2);
      sigmaVec[j] = clamp(sN, sigFloor, sigCeil);
    }
    if (noImp >= 2) noImp = 0;
    gen++;
  }

  var bestFinal = null;
  var bestFinalScore = -1e9;
  var bestFin = null;
  var bestAny = null;
  var qi;
  for (qi = 0; qi < allStats.length; qi++) {
    var stf = allStats[qi];
    if (stf.invalid) continue;
    if (!bestAny || stf.distance > bestAny.distance) bestAny = stf;
    if (stf.finished && (!bestFin || stf.distance > bestFin.distance)) bestFin = stf;

    var fs = stf.distance
           + (stf.finished ? 1.5 : 0)
           + 0.020 * Math.min(stf.time, 10)
           - stf.penalty;
    if (!stf.finished && stf.time < 1.0) fs -= 0.10;
    if (fs > bestFinalScore) {
      bestFinalScore = fs;
      bestFinal = stf;
    }
  }

  if (!bestFinal) {
    if (bestSeedStat && !bestSeedStat.invalid) return copyP(bestSeedStat.par);
    return makeP({});
  }

  if (bestFin && bestFin.distance >= 0.30) {
    if (!bestFinal.finished && bestFinal.distance < bestFin.distance + 1.0) {
      bestFinal = bestFin;
    }
  }
  if (bestAny && bestFinal.distance < 0.20 && bestAny.distance > 0.60) {
    bestFinal = bestAny;
  }

  return copyP(bestFinal.par);
}

var LIMLO = [
  -0.426,-0.54,-0.313,-0.438,-0.05,-0.797,-0.406,-0.967,-0.173,-0.753,-0.05,
  -0.443,-0.278,-0.573,-0.05,-0.892,-0.354,-0.965,-0.23,-0.771,-0.05
];
