  0.797,1.977,0.676,0.629,2.189,0.501,0.441,2.148,2.161,0.693,2.185,
  1.787,0.681,0.736,2.2,0.462,0.349,2.641,2.116,0.805,2.404
];
var SCALE = [
  1.10,1.20,1.00,0.80,1.30,1.10,1.00,
  1.00,0.90,0.70,0.80,
  1.20,1.00,0.80,1.30,1.10,1.00,
  1.00,0.90,0.70,0.80
];

var DEF = {
  gaitAmp: 0.0,
  period: 0.70,
  stanceFrac: 0.55,
  phaseOffset: 0.50,
  startup: 0.28,
  ramp: 0.55,
  hipBias: 0.0,
  hipOutBias: 0.10,
  kneeBias: 0.15,
  ankleBias: 0.0,
  waistBias: 0.0,
  shoulderOut: 0.16,
  elbowBias: 0.25,
  armBias: 0.0,
  armAmp: 0.0,
  hipAmp: 0.32,
  kneeSwing: 0.66,
  kneeLand: 0.16,
  kneePush: 0.05,
  ankleStance: 0.10,
  ankleSwing: 0.20,
  anklePush: 0.05,
  hipOutSwing: 0.05,
  hipOutStance: 0.0,
  hipTwistAmp: 0.0,
  latAmp: 0.0,
  latPhase: 0.0,
  pitchRef: 0.0,
  yawRef: 0.0,
  anklePitchP: 1.9,
  anklePitchD: 0.20,
  ankleRollP: 1.0,
  ankleRollD: 0.12,
  ankleRollSameP: 0.0,
  ankleRollSameD: 0.0,
  hipOutRollP: 0.0,
  hipOutRollD: 0.0,
  hipPitchP: 0.25,
  hipPitchD: 0.03,
  kneePitchP: 0.0,
  kneePitchD: 0.0,
  waistPitchP: -0.40,
  waistPitchD: -0.04,
  yawP: 0.25,
  yawD: 0.04,
  kp: 2.8,
  kd: 0.12,
  safetyTilt: 0.80,
  safetyGain: 1.2,
  recoverKnee: 0.12,
  recoverOut: 0.04,
  recoverArm: 0.20,
  terrainKnee: 0.20,
  terrainHip: 0.05,
  terrainDown: -0.10,
  terrainAnkle: 0.10,
  stumbleKnee: 0.15,
  stumbleHip: 0.05,
