  var joints = obs.joints || [];
  var speeds = obs.speeds || [];
  var feet = obs.feet || [0, 0];
  var j;

  if (!mem.init) {
    mem.init = true;
    mem.lastT = t;
    mem.roll = num(ori[0], 0);
    mem.pitch = num(ori[1], 0);
    mem.yaw = num(ori[2], 0);
    mem.rollRate = 0;
    mem.pitchRate = 0;
    mem.yawRate = 0;
    mem.qF = [];
    mem.dqF = [];
