  var dt = t - mem.lastT;
  if (!(dt > 0) || dt > 0.25) dt = 0.02;
  mem.lastT = t;

  var oldRoll = mem.roll;
  var oldPitch = mem.pitch;
  var oldYaw = mem.yaw;
  mem.roll = 0.70 * oldRoll + 0.30 * num(ori[0], oldRoll);
  mem.pitch = 0.70 * oldPitch + 0.30 * num(ori[1], oldPitch);
  mem.yaw = 0.70 * oldYaw + 0.30 * num(ori[2], oldYaw);

  var rRaw = (mem.roll - oldRoll) / Math.max(dt, 1e-3);
  var pRaw = (mem.pitch - oldPitch) / Math.max(dt, 1e-3);
  var yRaw = (mem.yaw - oldYaw) / Math.max(dt, 1e-3);
  mem.rollRate = 0.72 * mem.rollRate + 0.28 * rRaw;
  mem.pitchRate = 0.72 * mem.pitchRate + 0.28 * pRaw;
  mem.yawRate = 0.72 * mem.yawRate + 0.28 * yRaw;

  for (j = 0; j < 21; j++) {
    var qj = num(joints[j], mem.qF[j]);
    var dj = num(speeds[j], mem.dqF[j]);
    mem.qF[j] = 0.65 * mem.qF[j] + 0.35 * qj;
    mem.dqF[j] = 0.60 * mem.dqF[j] + 0.40 * dj;
  }

  var fLraw = Math.max(0, num(feet[0], 0));
  var fRraw = Math.max(0, num(feet[1], 0));
  mem.fL = 0.65 * mem.fL + 0.35 * fLraw;
  mem.fR = 0.65 * mem.fR + 0.35 * fRraw;
  var total = mem.fL + mem.fR;
  mem.maxLoad = Math.max(mem.maxLoad * 0.999, total);

  var active = smooth(clamp((t + 0.02) / Math.max(0.15, P.startup + 0.12), 0, 1));
  var g = 0;
  if (!mem.started && t >= P.startup) {
    mem.started = true;
    mem.phase = 0;
  }
  if (mem.started) {
    mem.phase = frac(mem.phase + dt / Math.max(0.12, P.period));
