  }

  var tilt = Math.max(Math.abs(mem.roll), Math.abs(mem.pitch - P.pitchRef));
  var over = Math.max(0, tilt - P.safetyTilt);
  var safeT = clamp(1 - over * P.safetyGain, 0, 1);
