  var aR = P.ankleRollP * eR + P.ankleRollD * mem.rollRate;
  var aRS = P.ankleRollSameP * eR + P.ankleRollSameD * mem.rollRate;
  var outR = P.hipOutRollP * eR + P.hipOutRollD * mem.rollRate;
  var hipP = P.hipPitchP * eP + P.hipPitchD * mem.pitchRate;
  var kneeP = P.kneePitchP * eP + P.kneePitchD * mem.pitchRate;
  var yawC = P.yawP * eY + P.yawD * mem.yawRate;

