  for (leg = 0; leg < 2; leg++) {
    var off = leg === 1 ? P.phaseOffset : 0;
    var ph = frac(mem.phase + off);
    var hipT = P.hipBias * active;
    var outT = P.hipOutBias * active;
    var kneeT = P.kneeBias * active;
    var ankT = P.ankleBias * active;
    var twT = 0;
    var swingF = 0;

    if (gSafe > 1e-6) {
      var sf = clamp(P.stanceFrac, 0.12, 0.88);
      if (ph < sf) {
        var s = ph / sf;
        hipT += gSafe * P.hipAmp * (1 - 2 * s);
        kneeT += gSafe * (P.kneeLand * (1 - s) * (1 - s) + P.kneePush * Math.sin(Math.PI * s));
        ankT += gSafe * (P.ankleStance * (1 - 2 * s) + P.anklePush * Math.sin(Math.PI * s));
        outT += gSafe * P.hipOutStance * (1 - 2 * s);
        twT += gSafe * P.hipTwistAmp * Math.sin(2 * Math.PI * ph);
      } else {
        var w = (ph - sf) / (1 - sf);
        var sw = smooth(w);
        hipT += gSafe * P.hipAmp * (-1 + 2 * sw);
        kneeT += gSafe * P.kneeSwing * Math.sin(Math.PI * w);
        ankT += gSafe * P.ankleSwing * Math.sin(Math.PI * w);
        outT += gSafe * P.hipOutSwing * Math.sin(Math.PI * w);
        twT += gSafe * P.hipTwistAmp * Math.sin(2 * Math.PI * ph);
        swingF = Math.sin(Math.PI * w);
