      if (swingF > 0.01 && obs.ground && obs.ground.length >= 18) {
        var c = leg === 0 ? 0 : 2;
        var h1 = num(obs.ground[c], 0);
        var h2 = num(obs.ground[3 + c], 0);
        var h3 = num(obs.ground[6 + c], 0);
        var hmax = Math.max(h1, h2, h3);
        var hmin = Math.min(h1, h2, h3);
        var up = Math.max(0, hmax);
        var dn = Math.min(0, hmin);
        kneeT += gSafe * swingF * (P.terrainKnee * up + P.terrainDown * dn);
        hipT += gSafe * swingF * P.terrainHip * up;
        ankT += gSafe * swingF * P.terrainAnkle * up;
      }

      if (total > 1e-6) {
        var load = leg === 0 ? mem.fL : mem.fR;
        var fracLoad = load / (total + 1e-9);
        if (swingF > 0.05) {
          var stumble = clamp((fracLoad - P.contactThresh) / (1 - P.contactThresh + 1e-6), 0, 1);
          kneeT += gSafe * stumble * P.stumbleKnee;
