    hipT += active * hipP;
    kneeT += active * kneeP;
    outT += active * (leg === 0 ? 1 : -1) * outR;
    kneeT += rec * P.recoverKnee;
    outT += rec * P.recoverOut;
    ankT += active * aP;

    var rollT = active * ((leg === 0 ? 1 : -1) * aR + aRS);
    var twBal = active * (leg === 0 ? 1 : -1) * yawC;

    var b = leg === 0 ? 1 : 11;
    target[b] = clamp(hipT, LIMLO[b], LIMHI[b]);
    target[b + 1] = clamp(outT, LIMLO[b + 1], LIMHI[b + 1]);
    target[b + 2] = clamp(twT + twBal, LIMLO[b + 2], LIMHI[b + 2]);
    target[b + 3] = clamp(kneeT, LIMLO[b + 3], LIMHI[b + 3]);
    target[b + 4] = clamp(ankT, LIMLO[b + 4], LIMHI[b + 4]);
    target[b + 5] = clamp(rollT, LIMLO[b + 5], LIMHI[b + 5]);
