  var pR = frac(mem.phase + P.phaseOffset);
  var armL = P.armBias * active + P.armAmp * gSafe * (-Math.cos(2 * Math.PI * pL));
  var armR = P.armBias * active + P.armAmp * gSafe * (-Math.cos(2 * Math.PI * pR));
