  target[7] = clamp(armL, LIMLO[7], LIMHI[7]);
  target[8] = clamp(shOut + active * P.armRollP * eR, LIMLO[8], LIMHI[8]);
  target[9] = 0;
  target[10] = clamp(P.elbowBias * active, LIMLO[10], LIMHI[10]);
  target[17] = clamp(armR, LIMLO[17], LIMHI[17]);
  target[18] = clamp(shOut - active * P.armRollP * eR, LIMLO[18], LIMHI[18]);
