    if (!isFinite(c)) c = 0;
    cmd[j] = clamp(c, -1, 1);
  }
  return cmd;
}

function learn(lab) {
  var used = 0;
  var records = [];
  var stablePool = [];
  var explorePool = [];
  var standPool = [];
  var standBest = null;

  function getTrialsLeft() {
    try {
      var x = lab.trialsLeft();
      if (x === undefined || x === null || !isFinite(x)) return 1000;
      return x;
    } catch (e) {
      return 1000;
    }
  }
  function getTimeLeft() {
    try {
      var x = lab.timeLeft();
      if (x === undefined || x === null || !isFinite(x)) return 1000;
      return x;
    } catch (e) {
      return 1000;
    }
  }
  function canTrial() {
    return used < 200 && getTrialsLeft() > 0 && getTimeLeft() > 0.65;
  }
  function randn() {
    var u1 = 0, u2 = 0;
    while (u1 === 0) u1 = Math.random();
    while (u2 === 0) u2 = Math.random();
    return Math.sqrt(-2 * Math.log(u1)) * Math.cos(2 * Math.PI * u2);
