      if (Object.prototype.hasOwnProperty.call(o, k)) r[k] = o[k];
    }
    return r;
  }

  function analyzeTrial(r) {
    var invalid = (!r || r.outcome === "invalid" || r.outcome === "error" || r.outcome === "exploit");
    var d = r ? Number(r.distance) : 0;
    if (!isFinite(d)) d = 0;
    var tm = r ? Number(r.time) : 0;
    if (!isFinite(tm)) tm = 0;
    var fin = !!(r && r.outcome === "finished");
    var energy = r ? Number(r.energy) : 0;
    if (!isFinite(energy)) energy = 0;
    var tr = (r && r.trace) ? r.trace : [];
    var maxRoll = 0, maxPitch = 0, maxSide = 0;
    var minH = 1e9, maxH = -1e9;
    var finalH = 0, finalRoll = 0, finalPitch = 0, finalSide = 0;
    var i;
    for (i = 0; i < tr.length; i++) {
      var row = tr[i];
      if (row && row.length >= 6) {
        var h = Math.abs(num(row[2], 0));
        var side = Math.abs(num(row[3], 0));
        var rr = Math.abs(num(row[4], 0));
        var pp = Math.abs(num(row[5], 0));
        if (h < minH) minH = h;
        if (h > maxH) maxH = h;
        if (side > maxSide) maxSide = side;
        if (rr > maxRoll) maxRoll = rr;
        if (pp > maxPitch) maxPitch = pp;
        finalH = h;
        finalSide = side;
        finalRoll = rr;
        finalPitch = pp;
