  function penaltyOf(m) {
    var pen = 0;
    if (m.maxRoll > 0.70) pen += (m.maxRoll - 0.70) * 20;
    if (m.maxPitch > 1.00) pen += (m.maxPitch - 1.00) * 15;
    if (m.minRatio < 0.55) pen += (0.55 - m.minRatio) * 30;
    if (m.maxSide > 1.50) pen += (m.maxSide - 1.50) * 15;
    if (m.finished && m.finalRatio < 0.70) pen += (0.70 - m.finalRatio) * 40;
    if (m.finished && m.finalAbsRoll > 0.50) pen += (m.finalAbsRoll - 0.50) * 30;
    if (m.finished && m.finalAbsPitch > 0.80) pen += (m.finalAbsPitch - 0.80) * 30;
    pen += Math.min(3, Math.abs(m.energy) * 1e-5);
    return pen;
  }

  function scoreTrial(rec) {
    var m = rec.metrics;
    if (m.invalid) return -1e12;
    var d = Math.max(-1, Math.min(30, m.distance));
    var tm = Math.max(0, Math.min(10, m.time));
    var sc = d * 10 + tm * 5 + (m.finished ? 20 : 0) - penaltyOf(m);
    if (!m.finished && tm < 1.0 && d < 0.2) sc -= 20;
