  }

  function standScoreOf(rec) {
    if (!rec || rec.metrics.invalid) return -1e12;
    var m = rec.metrics;
    var sc = (m.finished ? 1000 : 0) + Math.min(10, m.time) * 100;
    sc += clamp(m.minRatio, 0, 1.5) * 30;
    sc -= penaltyOf(m) * 15;
    if (m.finished && m.finalRatio < 0.75) sc -= (0.75 - m.finalRatio) * 250;
    if (m.finished && m.finalAbsRoll > 0.5) sc -= (m.finalAbsRoll - 0.5) * 160;
    if (m.finished && m.finalAbsPitch > 0.8) sc -= (m.finalAbsPitch - 0.8) * 160;
    return sc;
  }

  function finalVal(rec) {
    var m = rec.metrics;
    if (m.invalid) return -1e12;
    var d = Math.max(0, m.distance);
    var val = d;
    if (m.finished) {
      var fr = clamp(m.finalRatio, 0, 1.2);
      var ok = 1;
      if (m.finalRatio < 0.75) ok *= 0.50 + 0.50 * clamp(m.finalRatio / 0.75, 0, 1);
      if (m.finalAbsRoll > 0.5) ok *= 0.70;
      if (m.finalAbsPitch > 0.9) ok *= 0.80;
