    if (!isFinite(en)) en = 0;
    en = Math.abs(en);

    var tr = (r && r.trace && r.trace.length) ? r.trace : [];
    var maxRoll = 0, maxPitch = 0, maxSide = 0;
    var minH = 1e9;
    var h0 = 1;
    var lastRow = null;
    var i;

    if (tr.length > 0 && tr[0]) {
      var hh = num(tr[0][2], 0);
      if (hh > 0.05) h0 = hh;
    }

    for (i = 0; i < tr.length; i++) {
      var row = tr[i];
      if (!row || row.length < 6) continue;
      var h = num(row[2], h0);
      var side = Math.abs(num(row[3], 0));
      var rr = Math.abs(num(row[4], 0));
      var pp = Math.abs(num(row[5], 0));
      if (h < minH) minH = h;
      if (side > maxSide) maxSide = side;
      if (rr > maxRoll) maxRoll = rr;
      if (pp > maxPitch) maxPitch = pp;
      lastRow = row;
    }
    if (minH > 1e8) minH = h0;

    var finalRatio = 1;
    var finalSide = 0;
    var lastRoll = 0;
    var lastPitch = 0;
    if (lastRow) {
      var fh = num(lastRow[2], h0);
      finalRatio = fh / h0;
      finalSide = Math.abs(num(lastRow[3], 0));
      lastRoll = Math.abs(num(lastRow[4], 0));
      lastPitch = Math.abs(num(lastRow[5], 0));
    }

    return {
      invalid: inv,
      distance: d,
      time: tm,
      finished: fin,
      energy: en,
      maxRoll: maxRoll,
      maxPitch: maxPitch,
      maxSide: maxSide,
      minRatio: minH / h0,
      finalRatio: finalRatio,
      finalSide: finalSide,
      lastRoll: lastRoll,
      lastPitch: lastPitch
    };
  }

  function isStable(m) {
    return !m.invalid &&
           m.finished &&
           m.time > 9.80 &&
           m.finalRatio > 0.65 &&
           m.maxRoll < 0.90 &&
           m.maxPitch < 1.10 &&
           m.maxSide < 1.85 &&
           m.lastRoll < 0.65 &&
           m.lastPitch < 0.95;
  }

  function fitOf(m) {
    if (m.invalid) return -1e12;
    var d = Math.max(-1, m.distance);
    var tm = Math.min(10, m.time);
    var sc = 0;
    if (isStable(m)) sc += 10000;
    if (m.finished) sc += 650;
    sc += d * 100 + tm * 4;
    sc -= Math.max(0, m.maxRoll - 0.80) * 60;
    sc -= Math.max(0, m.maxPitch - 1.05) * 50;
    sc -= Math.max(0, m.maxSide - 1.70) * 80;
    if (m.finished && m.finalRatio < 0.70) {
      sc -= (0.70 - m.finalRatio) * 400;
    }
    sc -= Math.min(20, m.energy * 1e-6);
    if (!m.finished && m.time < 1.0) sc -= 100;
    return sc;
  }

  function finalVal(rec) {
    var m = rec.m;
    if (m.invalid) return -1e12;
    var d = Math.max(0, m.distance);
    if (isStable(m)) {
      var v = 100000 + d * 1000 + Math.min(10, m.time) * 10;
      v -= m.maxRoll * 40;
      v -= m.maxPitch * 30;
      v -= Math.max(0, m.maxSide - 1.0) * 80;
      v -= Math.max(0, 0.76 - m.finalRatio) * 1200;
      v -= Math.min(30, Math.abs(m.energy) * 1e-5);
      return v;
    }
    var u = d * 100 + Math.min(10, m.time) * 20 + (m.finished ? 30 : 0);
    u -= Math.max(0, m.maxRoll - 1.0) * 50;
    u -= Math.max(0, m.maxPitch - 1.2) * 40;
    u -= Math.max(0, m.maxSide - 1.8) * 50;
