    if (safePool.length > 0) {
      mutateOne(child, CORE[Math.floor(Math.random() * CORE.length)], scale * 0.90);
      var n1 = 1 + Math.floor(Math.random() * 3);
      var q1;
      for (q1 = 0; q1 < n1; q1++) {
        if (Math.random() < 0.62) {
