    var rec = evalP(child, "evolve");
    if (rec) {
      var val = rec.fit;
      if (val > bestNumeric + 1e-9) {
        bestNumeric = val;
        noImp = 0;
        scale = Math.max(0.28, scale * 0.86);
      } else {
        noImp++;
      }
      if (noImp > 14) {
        noImp = 0;
        scale = Math.min(1.55, scale * 1.18 + 0.04);
        if (Math.random() < 0.55 && safePool.length > 0) {
          var kick = copy(safePool[0].par);
          kick.gaitAmp = 0.06 + Math.random() * 0.65;
          kick.period = 0.42 + Math.random() * 0.95;
          kick.stanceFrac = 0.49 + Math.random() * 0.27;
          kick.hipAmp = 0.10 + Math.random() * 0.55;
          kick.kneeSwing = 0.25 + Math.random() * 1.00;
          kick.ankleSwing = 0.05 + Math.random() * 0.35;
          if (canTrial()) {
            evalP(kick, "kick");
          }
        }
      }
    } else {
      break;
    }
  }

  if (bestSafeRec) {
    return copy(bestSafeRec.par);
  }
  if (bestAnyRec && !bestAnyRec.m.invalid) {
    if (bestAnyRec.m.distance > 0.25 || bestAnyRec.m.time > 5.0) {
      return copy(bestAnyRec.par);
