    for (i = 1; i < finPool.length; i++) {
      if (finPool[i].m.distance > bestFin.m.distance) bestFin = finPool[i];
    }
    return copy(bestFin.par);
  }

  var fb = copy(DEF);
  fb.gaitAmp = 0.12;
  fb.period = 0.95;
  fb.stanceFrac = 0.66;
  fb.hipAmp = 0.20;
  fb.kneeSwing = 0.45;
  fb.ankleSwing = 0.14;
  fb.armAmp = 0.14;
  fb.startup = 0.40;
  fb.ramp = 0.65;
  return fb;
}

