function clamp(x, a, b) {
  x = Number(x);
  if (!isFinite(x)) return a;
  if (x < a) return a;
  if (x > b) return b;
  return x;
}
function num(x, d) {
  x = Number(x);
  return isFinite(x) ? x : d;
}
function smooth01(x) {
  x = clamp(x, 0, 1);
  return x * x * (3 - 2 * x);
}
function frac(x) {
  x = x - Math.floor(x);
  return x < 0 ? x + 1 : x;
}

function normP(params) {
  var P = {};
  var k;
  for (k in DEF) {
    if (Object.prototype.hasOwnProperty.call(DEF, k)) P[k] = DEF[k];
  }
  if (params && typeof params === "object") {
    for (k in DEF) {
      if (Object.prototype.hasOwnProperty.call(DEF, k) && params[k] !== undefined) {
        var v = Number(params[k]);
        if (isFinite(v)) P[k] = v;
      }
    }
  }
  P.gaitAmp = clamp(P.gaitAmp, 0.0, 1.5);
  P.period = clamp(P.period, 0.25, 2.0);
  P.stanceFrac = clamp(P.stanceFrac, 0.35, 0.85);
  P.phaseOffset = clamp(P.phaseOffset, 0.0, 1.0);
  P.startPhase = clamp(P.startPhase, 0.0, 1.0);
  P.startup = clamp(P.startup, 0.0, 1.5);
  P.ramp = clamp(P.ramp, 0.05, 2.0);
  P.kp = clamp(P.kp, 0.2, 10.0);
  P.kd = clamp(P.kd, 0.0, 2.0);
  P.contactThresh = clamp(P.contactThresh, 0.01, 0.80);
  P.safeTilt = clamp(P.safeTilt, 0.10, 2.0);
  P.safeRoll = clamp(P.safeRoll, 0.10, 2.0);
  P.safeGain = clamp(P.safeGain, 0.0, 12.0);
  return P;
}

function policy(obs, params, mem) {
