function clamp(x,a,b){
  x = Number(x);
  if (!isFinite(x)) return a;
  if (x < a) return a;
  if (x > b) return b;
  return x;
}
function num(x,d){
  x = Number(x);
  return isFinite(x) ? x : d;
}
function smooth01(x){
  x = clamp(x,0,1);
  return x*x*(3-2*x);
}
function frac(x){
  x = x - Math.floor(x);
  return x < 0 ? x + 1 : x;
}
function wrapPi(x){
  while (x > Math.PI) x -= 2*Math.PI;
  while (x < -Math.PI) x += 2*Math.PI;
  return x;
}

function normP(params){
  var P = {};
  var k;
  for (k in DEF){
    if (Object.prototype.hasOwnProperty.call(DEF,k)) P[k] = DEF[k];
  }
  if (params && typeof params === "object"){
    for (k in DEF){
      if (Object.prototype.hasOwnProperty.call(DEF,k) && params[k] !== undefined){
        var v = Number(params[k]);
        if (isFinite(v)) P[k] = v;
      }
    }
  }
  P.gaitAmp = clamp(P.gaitAmp,0,1.35);
  P.period = clamp(P.period,0.20,2.50);
  P.phaseOffset = clamp(P.phaseOffset,0,1);
  P.stanceFrac = clamp(P.stanceFrac,0.28,0.86);
  P.startTime = clamp(P.startTime,0,3);
  P.ramp = clamp(P.ramp,0.05,2.5);
  P.kp = clamp(P.kp,0.2,14);
  P.kd = clamp(P.kd,0,3);
  P.kpArm = clamp(P.kpArm,0.1,10);
  P.kdArm = clamp(P.kdArm,0,2);
  P.oriFilter = clamp(P.oriFilter,0.05,0.95);
  P.rateFilter = clamp(P.rateFilter,0.05,0.98);
  P.safeP = clamp(P.safeP,0.10,1.5);
  P.safeR = clamp(P.safeR,0.10,1.5);
  P.safeGain = clamp(P.safeGain,0,15);
  P.recDamp = clamp(P.recDamp,0,1.3);
  P.contactThresh = clamp(P.contactThresh,0.01,0.70);
  P.lungeStart = clamp(P.lungeStart,-1,9999);
  P.lungeRamp = clamp(P.lungeRamp,0.03,1.5);
  P.lungeBalance = clamp(P.lungeBalance,0,2);
  P.lungeGait = clamp(P.lungeGait,0,2);
  return P;
}

function policy(obs, params, mem){
  obs = obs || {};
  mem = mem || {};

  var P = mem._P;
  if (!P){
    P = normP(params);
    mem._P = P;
  }

  var t = num(obs.t,0);
  var ori = obs.orientation || [0,0,0];
  var gyro = obs.gyro || [0,0,0];
  var joints = obs.joints || [];
  var speeds = obs.speeds || [];
  var feet = obs.feet || [0,0];
  var ground = obs.ground || [];
  var j, leg;

  if (!mem.init){
    mem.init = true;
    mem.lastT = t;
    mem.roll = num(ori[0],0);
    mem.pitch = num(ori[1],0);
    mem.yaw = num(ori[2],0);
    mem.lastRawR = mem.roll;
    mem.lastRawP = mem.pitch;
    mem.lastRawY = mem.yaw;
    mem.rateR = 0;
    mem.rateP = 0;
    mem.rateY = 0;
    mem.intP = 0;
    mem.intR = 0;
    mem.qF = [];
    mem.dqF = [];
    for (j=0;j<21;j++){
      mem.qF[j] = num(joints[j],0);
      mem.dqF[j] = num(speeds[j],0);
    }
    mem.fL = Math.max(0,num(feet[0],0));
    mem.fR = Math.max(0,num(feet[1],0));
    mem.maxLoad = Math.max(0.01,mem.fL+mem.fR);
    mem.phase = 0;
    mem.started = false;
    mem.rec = 0;
    mem.air = 0;
  }

  var dt = t - mem.lastT;
  if (!(dt > 0) || dt > 0.20) dt = 0.02;
  mem.lastT = t;

  var rawR = num(ori[0],mem.roll);
  var rawP = num(ori[1],mem.pitch);
  var rawY = num(ori[2],mem.yaw);

  var af = P.oriFilter;
  mem.roll += af * (rawR - mem.roll);
  mem.pitch += af * (rawP - mem.pitch);
  mem.yaw += af * wrapPi(rawY - mem.yaw);

  var dR = (rawR - mem.lastRawR) / Math.max(dt,1e-3);
  var dP = (rawP - mem.lastRawP) / Math.max(dt,1e-3);
  var dY = (rawY - mem.lastRawY) / Math.max(dt,1e-3);
  mem.lastRawR = rawR;
  mem.lastRawP = rawP;
  mem.lastRawY = rawY;

  var rf = P.rateFilter;
  mem.rateR = rf*mem.rateR + (1-rf)*(0.62*num(gyro[0],0) + 0.38*dR);
  mem.rateP = rf*mem.rateP + (1-rf)*(0.62*num(gyro[1],0) + 0.38*dP);
  mem.rateY = rf*mem.rateY + (1-rf)*(0.62*num(gyro[2],0) + 0.38*dY);

  for (j=0;j<21;j++){
    var qj = num(joints[j],mem.qF[j]);
    var dj = num(speeds[j],mem.dqF[j]);
    mem.qF[j] = 0.70*mem.qF[j] + 0.30*qj;
    mem.dqF[j] = 0.65*mem.dqF[j] + 0.35*dj;
  }

  var rawFL = Math.max(0,num(feet[0],0));
  var rawFR = Math.max(0,num(feet[1],0));
  mem.fL = 0.66*mem.fL + 0.34*rawFL;
  mem.fR = 0.66*mem.fR + 0.34*rawFR;
  var totalF = mem.fL + mem.fR;
  mem.maxLoad = Math.max(mem.maxLoad*0.9995,totalF,0.005);

  var denom = 0.06*mem.maxLoad + 1e-9;
  var cL = smooth01(clamp((mem.fL - P.contactThresh*mem.maxLoad)/denom,0,1));
  var cR = smooth01(clamp((mem.fR - P.contactThresh*mem.maxLoad)/denom,0,1));

  var eP = mem.pitch - P.pitchRef;
  var eR = mem.roll - P.rollRef;
  var eY = wrapPi(mem.yaw - P.yawRef);

  mem.intP = clamp(mem.intP*0.995 + eP*dt,-1.0,1.0);
  mem.intR = clamp(mem.intR*0.995 + eR*dt,-1.0,1.0);

  var overP = Math.max(0,Math.abs(eP)-P.safeP);
  var overR = Math.max(0,Math.abs(eR)-P.safeR);
  var recNow = clamp((overP+overR)*P.safeGain,0,1);
  var airNow = (cL < 0.10 && cR < 0.10) ? 1 : 0;
  mem.air = 0.92*mem.air + 0.08*airNow;
  recNow = Math.max(recNow,mem.air*P.airDamp);
  mem.rec = 0.90*mem.rec + 0.10*recNow;

  var pose = smooth01(t/Math.max(0.05,P.poseTime));

  if (!mem.started && t >= P.startTime){
    mem.started = true;
    mem.phase = P.startPhase;
  }

  var phaseRamp = 0;
  if (mem.started){
    var pSpeed = 1 + P.phaseP*eP + P.phaseD*mem.rateP;
    pSpeed = clamp(pSpeed,0.20,3.0);
    mem.phase = frac(mem.phase + dt/Math.max(0.10,P.period)*pSpeed);
    phaseRamp = smooth01((t-P.startTime)/Math.max(0.05,P.ramp));
  }

  var g = P.gaitAmp * phaseRamp * (1 - P.recDamp*mem.rec);
  if (g < 0) g = 0;

  var lunge = 0;
  if (t >= P.lungeStart){
    lunge = smooth01((t-P.lungeStart)/Math.max(0.03,P.lungeRamp));
  }
  if (lunge > 0) g *= clamp(1-P.lungeGait*lunge,0,1);
  var bal = 1 - P.lungeBalance*lunge;

  var baseHip = P.hip0*pose;
  var baseKnee = P.knee0*pose;
  var baseAnkle = P.ankle0*pose;
  var baseOut = P.out0*pose;
  var baseWaist = P.waist0*pose;
  var baseArmFwd = P.armFwd0*pose;
  var baseArmOut = P.armOut0*pose;
  var baseElbow = P.elbow0*pose;

  var target = [];
  for (j=0;j<21;j++) target[j] = 0;

  var sf = clamp(P.stanceFrac,0.28,0.86);

  for (leg=0; leg<2; leg++){
    var off = leg === 0 ? 0 : P.phaseOffset;
    var ph = frac(mem.phase + off);
    var isSwing = ph >= sf;
    var hip = baseHip;
    var knee = baseKnee;
    var ank = baseAnkle;
    var out = baseOut;
    var twist = 0;
    var rollT = 0;
    var sw = 0;

    if (g > 1e-7){
      if (!isSwing){
        var u = ph/Math.max(1e-6,sf);
        var waveH = 1 - 2*u;
        var waveK = P.kneeLand*(1-u)*(1-u) + P.kneeStance*Math.sin(Math.PI*u) + P.kneePush*Math.sin(Math.PI*u);
        var waveA = P.ankleStance*(1-2*u) + P.anklePush*Math.sin(Math.PI*u);
        var waveO = P.outStance*(1-2*u);
        hip += g*P.hipAmp*waveH;
        knee += g*waveK;
        ank += g*waveA;
        out += g*waveO;
      } else {
        var w = (ph-sf)/Math.max(1e-6,1-sf);
        sw = Math.sin(Math.PI*clamp(w,0,1));
        var sm = smooth01(w);
        hip += g*P.hipAmp*(-1 + 2*sm);
        knee += g*P.kneeSwing*sw;
        ank += g*P.ankleSwing*sw;
        out += g*P.outSwing*sw;
      }

      out += g*P.latAmp*(leg===0?1:-1)*Math.sin(2*Math.PI*mem.phase + P.latPhase);
    }

    if (isSwing){
      hip += P.swingHipP*eP + P.swingHipD*mem.rateP;
      out += (leg===0?1:-1)*(P.swingOutP*eR + P.swingOutD*mem.rateR);
    } else {
      hip += P.stanceHipP*eP + P.stanceHipD*mem.rateP;
    }

    knee += P.recKnee*mem.rec + P.airKnee*mem.air;
    out += P.recOut*mem.rec + P.airOut*mem.air;
    hip += P.recHip*mem.rec;
    ank += P.recAnkle*mem.rec + P.airAnkle*mem.air;

    if (g > 1e-5 && isSwing && ground.length >= 18){
      var c = leg === 0 ? 0 : 2;
      var gh0 = num(ground[c],0);
      var gh1 = num(ground[3+c],0);
      var gh2 = num(ground[6+c],0);
      var ghc0 = num(ground[1],0);
      var ghc1 = num(ground[4],0);
      var up = Math.max(0,gh0,gh1*0.80,gh2*0.50,ghc0*0.50,ghc1*0.30);
      var dn = Math.min(0,gh0,gh1*0.80,gh2*0.50,ghc0*0.50,ghc1*0.30);
      var lift = Math.max(0.10,sw);
      knee += (P.terrainKnee*up + P.terrainDownKnee*dn)*lift;
      hip += (P.terrainHip*up + P.terrainDownHip*dn)*lift;
      ank += (P.terrainAnkle*up + P.terrainDownAnkle*dn)*lift;
    }

    if (g > 1e-5 && isSwing){
      var f = leg === 0 ? mem.fL : mem.fR;
      var fden = Math.max(0.02,mem.fL+mem.fR);
      var cl = clamp((f - P.contactThresh*fden)/(0.12*fden+1e-6),0,1);
      if (cl > 0.05){
        var ww = (ph-sf)/Math.max(1e-6,1-sf);
        var st = cl*Math.max(0,1-ww);
        knee += P.stumbleKnee*st;
        hip += P.stumbleHip*st;
        ank += P.stumbleAnkle*st;
      }
    }

    if (lunge > 0){
      hip = hip*(1-lunge) + P.lungeHip*lunge;
      knee = knee*(1-lunge) + P.lungeKnee*lunge;
      ank = ank*(1-lunge) + P.lungeAnkle*lunge;
      out = out*(1-lunge) + P.lungeOut*lunge;
    }

    var b = leg === 0 ? 1 : 11;
    target[b] = clamp(hip,LIMLO[b],LIMHI[b]);
    target[b+1] = clamp(out,LIMLO[b+1],LIMHI[b+1]);
    target[b+2] = clamp(twist,LIMLO[b+2],LIMHI[b+2]);
    target[b+3] = clamp(knee,LIMLO[b+3],LIMHI[b+3]);
    target[b+4] = clamp(ank,LIMLO[b+4],LIMHI[b+4]);
    target[b+5] = clamp(rollT,LIMLO[b+5],LIMHI[b+5]);
  }

  var waist = baseWaist;
  if (lunge > 0) waist = waist*(1-lunge) + P.lungeWaist*lunge;
  target[0] = clamp(waist,LIMLO[0],LIMHI[0]);

  var phL = frac(mem.phase);
  var phR = frac(mem.phase + P.phaseOffset);
  var armSwingL = g*P.armAmp*Math.cos(2*Math.PI*(phL+P.armPhase));
  var armSwingR = g*P.armAmp*Math.cos(2*Math.PI*(phR+P.armPhase));

  var armL = baseArmFwd + armSwingL + P.armPitchP*eP + P.armPitchD*mem.rateP;
  var armR = baseArmFwd + armSwingR + P.armPitchP*eP + P.armPitchD*mem.rateP;
  var shOutL = baseArmOut + P.armRollP*eR + P.armRollD*mem.rateR + P.recArm*mem.rec;
  var shOutR = baseArmOut - P.armRollP*eR - P.armRollD*mem.rateR + P.recArm*mem.rec;
  var elbowL = baseElbow;
  var elbowR = baseElbow;

  if (lunge > 0){
    armL = armL*(1-lunge) + P.lungeArmFwd*lunge;
    armR = armR*(1-lunge) + P.lungeArmFwd*lunge;
    shOutL = shOutL*(1-lunge) + P.lungeArmOut*lunge;
    shOutR = shOutR*(1-lunge) + P.lungeArmOut*lunge;
    elbowL = elbowL*(1-lunge) + P.lungeElbow*lunge;
    elbowR = elbowR*(1-lunge) + P.lungeElbow*lunge;
  }

  target[7] = clamp(armL,LIMLO[7],LIMHI[7]);
  target[8] = clamp(shOutL,LIMLO[8],LIMHI[8]);
  target[9] = 0;
  target[10] = clamp(elbowL,LIMLO[10],LIMHI[10]);
  target[17] = clamp(armR,LIMLO[17],LIMHI[17]);
  target[18] = clamp(shOutR,LIMLO[18],LIMHI[18]);
  target[19] = 0;
  target[20] = clamp(elbowR,LIMLO[20],LIMHI[20]);

  var cmd = [];
  for (j=0;j<21;j++){
    var tv = clamp(target[j],LIMLO[j],LIMHI[j]);
    var err = tv - mem.qF[j];
    var isArm = ((j>=7 && j<=10) || (j>=17 && j<=20));
    var kpj = isArm ? P.kpArm : P.kp;
    var kvj = isArm ? P.kdArm : P.kd;
    var cval = kpj*KP_S[j]*err - kvj*KD_S[j]*mem.dqF[j];
    if (!isFinite(cval)) cval = 0;
    cmd[j] = clamp(cval,-1,1);
  }

  var cwl = 0.15 + 0.85*cL;
  var cwr = 0.15 + 0.85*cR;

  var aP = (P.ankP*eP + P.ankD*mem.rateP + P.ankI*mem.intP)*bal;
  cmd[5] += aP*cwl;
  cmd[15] += aP*cwr;

  var hP = (P.hipP*eP + P.hipD*mem.rateP + P.hipI*mem.intP)*bal;
  cmd[1] += hP*cwl;
  cmd[11] += hP*cwr;

  var kP = (P.kneeP*eP + P.kneeD*mem.rateP)*bal;
  cmd[4] += kP*cwl;
  cmd[14] += kP*cwr;

  var wP = (P.waistP*eP + P.waistD*mem.rateP + P.waistI*mem.intP)*bal;
  cmd[0] += wP;

  var aR = (P.ankRollP*eR + P.ankRollD*mem.rateR + P.ankRollI*mem.intR)*bal;
  var aRD = (P.ankRollDiffP*eR + P.ankRollDiffD*mem.rateR)*bal;
  cmd[6] += (aR + aRD)*cwl;
  cmd[16] += (aR - aRD)*cwr;

  var hO = (P.hipOutP*eR + P.hipOutD*mem.rateR + P.hipOutI*mem.intR)*bal;
  var hOD = (P.hipOutDiffP*eR + P.hipOutDiffD*mem.rateR)*bal;
  cmd[2] += (hO + hOD)*cwl;
  cmd[12] += (hO - hOD)*cwr;

  var yP = (P.yawP*eY + P.yawD*mem.rateY)*bal;
  cmd[3] += yP;
  cmd[13] -= yP;

  var armP = (P.armPitchP*eP + P.armPitchD*mem.rateP)*bal;
  cmd[7] += armP;
  cmd[17] += armP;

  var armRol = (P.armRollP*eR + P.armRollD*mem.rateR)*bal;
  cmd[8] += armRol;
  cmd[18] -= armRol;

  var lp = lunge;
  var pulse = 4*lp*(1-lp);
  cmd[1] += P.lungeHipCmd*pulse;
  cmd[11] += P.lungeHipCmd*pulse;
  cmd[4] += P.lungeKneeCmd*pulse;
  cmd[14] += P.lungeKneeCmd*pulse;
  cmd[5] += P.lungeAnkleCmd*pulse;
  cmd[15] += P.lungeAnkleCmd*pulse;
  cmd[0] += P.lungeWaistCmd*pulse;
  cmd[7] += P.lungeArmCmd*pulse;
  cmd[17] += P.lungeArmCmd*pulse;

  for (j=0;j<21;j++) cmd[j] = clamp(cmd[j],-1,1);
  return cmd;
}

function learn(lab){
  var used = 0;
  var all = [];
  var pool = [];
  var stablePool = [];
  var standPool = [];
  var perfPool = [];
  var gaitPool = [];

  function has(o,k){
    return Object.prototype.hasOwnProperty.call(o,k);
  }
  function copy(o){
    var r = {};
    var k;
    if (!o) return r;
    for (k in o){
      if (has(o,k)) r[k] = o[k];
    }
    return r;
  }
  function fill(par){
    var o = {};
    var k;
    for (k in DEF){
      if (has(DEF,k)) o[k] = DEF[k];
    }
    if (par && typeof par === "object"){
      for (k in DEF){
        if (has(DEF,k) && par[k] !== undefined){
          var v = Number(par[k]);
          if (isFinite(v)) o[k] = v;
        }
      }
    }
    return o;
  }
  function mk(over,base){
    var o = base ? copy(base) : fill(DEF);
    var k;
    if (over){
      for (k in over){
        if (has(over,k)) o[k] = over[k];
      }
    }
    return fill(o);
  }
  function getTrialsLeft(){
    try {
      var x = lab.trialsLeft();
      if (x === undefined || x === null || !isFinite(x)) return 1000;
      return x;
    } catch(e) {
      return 1000;
    }
  }
  function getTimeLeft(){
    try {
      var x = lab.timeLeft();
      if (x === undefined || x === null || !isFinite(x)) return 1000;
      return x;
    } catch(e) {
      return 1000;
    }
  }
  function canTrial(){
    return used < 200 && getTrialsLeft() > 0 && getTimeLeft() > 0.70;
  }
  function randn(){
    var u1 = 0, u2 = 0;
    while (u1 === 0) u1 = Math.random();
    while (u2 === 0) u2 = Math.random();
    return Math.sqrt(-2*Math.log(u1))*Math.cos(2*Math.PI*u2);
  }

  function metric(r){
    var inv = (!r ||
      r.outcome === "invalid" ||
      r.outcome === "error" ||
      r.outcome === "exploit");
    var d = r ? Number(r.distance) : 0;
    if (!isFinite(d)) d = 0;
    var tm = r ? Number(r.time) : 0;
    if (!isFinite(tm)) tm = 0;
    var fin = !!(r && r.outcome === "finished") || tm >= 9.55;
    var en = r ? Number(r.energy) : 0;
    if (!isFinite(en)) en = 0;

    var tr = (r && r.trace && r.trace.length) ? r.trace : [];
    var h0 = 1.0;
    var i;
    if (tr.length > 0 && tr[0] && tr[0].length >= 3){
      var hh = Math.abs(num(tr[0][2],0));
      if (hh > 0.05) h0 = hh;
    }

    var minH = 1e9;
    var maxRoll = 0;
    var maxPitch = 0;
    var maxSide = 0;
    var finalRatio = 1.0;
    var finalRoll = 0.0;
    var finalPitch = 0.0;
    var finalSide = 0.0;
    var rows = [];
    var last = null;

    for (i=0;i<tr.length;i++){
      var row = tr[i];
      if (!row || row.length < 6) continue;
      var tt = num(row[0],0);
      var dd = num(row[1],0);
      var hh2 = Math.abs(num(row[2],h0));
      var side = Math.abs(num(row[3],0));
      var rr = Math.abs(num(row[4],0));
      var pp = Math.abs(num(row[5],0));
      if (hh2 < minH) minH = hh2;
      if (side > maxSide) maxSide = side;
      if (rr > maxRoll) maxRoll = rr;
      if (pp > maxPitch) maxPitch = pp;
      rows.push({t:tt,d:dd,h:hh2,side:side,roll:rr,pitch:pp});
      last = row;
    }
    if (minH > 1e8) minH = h0;
    if (last){
      finalRatio = Math.abs(num(last[2],h0))/h0;
      finalRoll = Math.abs(num(last[4],0));
      finalPitch = Math.abs(num(last[5],0));
      finalSide = Math.abs(num(last[3],0));
    }

    return {
      invalid: inv,
      distance: d,
      time: tm,
      finished: fin,
      energy: Math.abs(en),
      h0: h0,
      minRatio: minH/h0,
      maxRoll: maxRoll,
      maxPitch: maxPitch,
      maxSide: maxSide,
      finalRatio: finalRatio,
      finalRoll: finalRoll,
      finalPitch: finalPitch,
      finalSide: finalSide,
      rows: rows
    };
  }

  function distanceAt(m,T){
    if (!m || m.invalid) return -1e18;
    if (T >= m.time - 0.01) return m.distance;
    var d = 0;
    var i;
    for (i=0;i<m.rows.length;i++){
      if (m.rows[i].t <= T + 1e-9) d = m.rows[i].d;
      else break;
    }
    return d;
  }

  function isStable(m){
    return !m.invalid &&
      m.finished &&
      m.time > 9.40 &&
      m.minRatio > 0.52 &&
      m.finalRatio > 0.65 &&
      m.maxRoll < 0.88 &&
      m.maxPitch < 1.00 &&
      m.maxSide < 1.75 &&
      m.finalRoll < 0.50 &&
      m.finalPitch < 0.70;
  }

  function raceScore(m){
    if (m.invalid) return -1e18;
    var d = Math.max(-1,m.distance);
    var tm = Math.min(10,m.time);
    var s = d*180 + tm*45;
    s -= Math.max(0,m.maxRoll-0.95)*800;
    s -= Math.max(0,m.maxPitch-1.05)*800;
    s -= Math.max(0,m.maxSide-1.90)*900;
    if (m.finished){
      s += 100000 + d*900;
      if (isStable(m)){
        s += 1000000000 + d*25000 + m.minRatio*1000 + m.finalRatio*1000;
      } else {
        s -= Math.max(0,0.70-m.finalRatio)*60000;
        s -= Math.max(0,m.finalRoll-0.55)*40000;
        s -= Math.max(0,m.finalPitch-0.80)*40000;
      }
    } else {
      s -= (10-tm)*6;
    }
    return s;
  }

  function perfScore(m){
    if (m.invalid) return -1e18;
    var s = m.distance*1000 + Math.min(10,m.time)*120;
    if (m.finished) s += 1500 + m.distance*300;
    s -= Math.max(0,m.maxRoll-1.05)*300;
    s -= Math.max(0,m.maxPitch-1.20)*300;
    s -= Math.max(0,m.maxSide-2.00)*400;
    if (m.finished){
      s -= Math.max(0,0.65-m.finalRatio)*20000;
      s -= Math.max(0,m.finalRoll-0.60)*15000;
      s -= Math.max(0,m.finalPitch-0.85)*15000;
    }
    return s;
  }

  function standScore(m){
    if (m.invalid) return -1e18;
    var s = 0;
    if (m.finished) s += 100000000;
    s += Math.min(10,m.time)*12000;
    s += m.minRatio*2500 + m.finalRatio*1600;
    s -= Math.max(0,m.maxRoll-0.60)*12000;
    s -= Math.max(0,m.maxPitch-0.75)*12000;
    s -= Math.max(0,m.maxSide-1.30)*10000;
    if (m.finished){
      s -= Math.max(0,0.78-m.finalRatio)*50000;
      s -= Math.max(0,m.finalRoll-0.45)*40000;
      s -= Math.max(0,m.finalPitch-0.60)*40000;
    } else {
      s -= (10-m.time)*800;
    }
    s += m.distance*10;
    return s;
  }

  function stableValue(m){
    var d = Math.max(0,m.distance);
    var val = d*2.5;
    if (m.time > 8) val *= 2;
    val += m.minRatio*0.6 + m.finalRatio*0.6;
    val -= Math.max(0,m.finalRoll-0.35)*0.8;
    val -= Math.max(0,m.finalPitch-0.55)*0.8;
    return val;
  }

  function addRec(rec){
    all.push(rec);
    if (rec.m.invalid) return;

    rec.race = raceScore(rec.m);
    rec.perf = perfScore(rec.m);
    rec.stand = standScore(rec.m);
    rec.stable = isStable(rec.m);

    pool.push(rec);
    pool.sort(function(a,b){ return b.race - a.race; });
    if (pool.length > 80) pool.length = 80;

    perfPool.push(rec);
    perfPool.sort(function(a,b){ return b.perf - a.perf; });
    if (perfPool.length > 60) perfPool.length = 60;

    if (rec.par.gaitAmp > 0.02 && rec.par.lungeStart > 100){
      gaitPool.push(rec);
      gaitPool.sort(function(a,b){ return b.perf - a.perf; });
      if (gaitPool.length > 50) gaitPool.length = 50;
    }

    if (rec.stable){
      stablePool.push(rec);
      stablePool.sort(function(a,b){ return stableValue(b.m) - stableValue(a.m); });
      if (stablePool.length > 45) stablePool.length = 45;
    }

    if (rec.par.gaitAmp <= 0.02 && rec.par.lungeStart > 100){
      standPool.push(rec);
      standPool.sort(function(a,b){ return b.stand - a.stand; });
      if (standPool.length > 45) standPool.length = 45;
    }
  }

  function runTrial(par){
    if (!canTrial()) return null;
    var p = fill(par);
    var r;
    try {
      r = lab.trial(p);
    } catch(e) {
      return null;
    }
    used++;
    var m = metric(r);
    return {par:p,m:m,tag:""};
  }

  function evalAdd(par,tag){
    var rec = runTrial(par);
    if (rec){
      rec.tag = tag;
      addRec(rec);
    }
    return rec;
  }

  var SPEC = [
    ["hip0",-0.6,0.9,0.05],
    ["knee0",0.0,0.85,0.035],
    ["ankle0",-0.7,0.4,0.03],
    ["out0",0.0,0.45,0.02],
    ["waist0",-0.5,0.7,0.03],
    ["armFwd0",-1.0,1.2,0.06],
    ["armOut0",0.0,0.9,0.03],
    ["elbow0",0.0,1.2,0.04],
    ["pitchRef",-0.25,0.45,0.02],
    ["rollRef",-0.12,0.12,0.005],
