    for (q=0; q<starts.length && canTrial(); q++){
      var im = copy(bestLungeRec.par);
      im.lungeStart = starts[q];
      im.lungeRamp = 0.20;
      im.lungeGait = 1.0;
      im.lungeBalance = clamp(im.lungeBalance,0,1.2);
