  }

  function predicted(rec){
    if (!rec || !rec.m || rec.m.invalid) return -1e18;
    var m = rec.m;
    var d = Math.max(0,m.distance);
    if (m.finished) d *= 1.75;
    else d += 0.05*Math.min(m.time,4);
    d -= Math.max(0,m.maxRoll-1.1)*0.5;
    d -= Math.max(0,m.maxPitch-1.3)*0.5;
    return d;
  }

  if (bestStableRec){
    var out = copy(bestStableRec.par);
    out.lungeStart = 999;

    var speed = bestStableRec.m.distance/Math.max(0.1,Math.min(10,bestStableRec.m.time));
    var lAdv = bestLungeRec ? bestLungeRec.lungeAdv : -1e9;
    var enableLunge = false;

    if (bestLungeRec && lAdv > speed*lungeHorizon + 0.04){
      enableLunge = true;
    }

    if (enableLunge){
      var lf = [
        "lungeRamp","lungeHip","lungeKnee","lungeAnkle","lungeWaist","lungeOut",
        "lungeArmFwd","lungeArmOut","lungeElbow","lungeBalance","lungeGait",
        "lungeHipCmd","lungeKneeCmd","lungeAnkleCmd","lungeWaistCmd","lungeArmCmd"
      ];
      var fi;
      for (fi=0; fi<lf.length; fi++){
        out[lf[fi]] = bestLungeRec.par[lf[fi]];
      }
      out.lungeStart = 20.0 - lungeHorizon;
      out.lungeRamp = clamp(out.lungeRamp,0.06,0.60);
    }

    return fill(out);
  }

  var bestStdRec = perfPool.length > 0 ? perfPool[0] : null;
  var bestImm = null;
  var ii;
  for (ii=0; ii<immediateRecs.length; ii++){
    var candI = immediateRecs[ii];
    var mI = candI.m;
    candI._pred = predicted({m:mI,par:candI});
    if (!bestImm || candI._pred > bestImm._pred) bestImm = candI;
  }

  if (bestStdRec && bestImm){
    var pStd = predicted(bestStdRec);
    var pImm = bestImm._pred;
    if (pImm > pStd + 0.05){
      return fill(bestImm);
    } else {
      return fill(bestStdRec.par);
    }
  }
  if (bestImm){
    return fill(bestImm);
  }
  if (bestStdRec){
    return fill(bestStdRec.par);
  }
  if (bestLungeRec){
    var fb = copy(bestLungeRec.par);
    fb.lungeStart = 0.25;
    return fill(fb);
  }
  if (standPool.length > 0) return fill(standPool[0].par);
  return fill(baseStand);
}

