};

function clamp(x,a,b){
  x = Number(x);
  if (!isFinite(x)) return a;
  if (x < a) return a;
  if (x > b) return b;
  return x;
}
function num(x,d){
  x = Number(x);
  return isFinite(x) ? x : d;
}
function smooth01(x){
  x = clamp(x,0,1);
  return x*x*(3-2*x);
}
function frac(x){
  x = x - Math.floor(x);
  return x < 0 ? x + 1 : x;
}
function wrapPi(x){
  while (x > Math.PI) x -= 2*Math.PI;
  while (x < -Math.PI) x += 2*Math.PI;
  return x;
}

function normP(params){
  var P = {};
  var k;
  for (k in DEF){
    if (Object.prototype.hasOwnProperty.call(DEF,k)) P[k] = DEF[k];
  }
  if (params && typeof params === "object"){
    for (k in DEF){
      if (Object.prototype.hasOwnProperty.call(DEF,k) && params[k] !== undefined){
        var v = Number(params[k]);
        if (isFinite(v)) P[k] = v;
      }
    }
  }
  P.poseTime = clamp(P.poseTime,0.05,1.5);
  P.kp = clamp(P.kp,0.2,15.0);
  P.kd = clamp(P.kd,0.0,2.0);
  P.kpArm = clamp(P.kpArm,0.2,10.0);
  P.kdArm = clamp(P.kdArm,0.0,2.0);
  P.ankP = clamp(P.ankP,-10.0,10.0);
  P.ankD = clamp(P.ankD,-6.0,6.0);
  P.ankI = clamp(P.ankI,-4.0,4.0);
  P.hipP = clamp(P.hipP,-8.0,8.0);
  P.hipD = clamp(P.hipD,-5.0,5.0);
  P.hipI = clamp(P.hipI,-3.0,3.0);
  P.waistP = clamp(P.waistP,-10.0,10.0);
  P.waistD = clamp(P.waistD,-6.0,6.0);
  P.waistI = clamp(P.waistI,-3.0,3.0);
  P.kneeP = clamp(P.kneeP,-5.0,5.0);
  P.kneeD = clamp(P.kneeD,-4.0,4.0);
  P.outP = clamp(P.outP,-10.0,10.0);
  P.outD = clamp(P.outD,-6.0,6.0);
  P.outI = clamp(P.outI,-3.0,3.0);
  P.ankRollP = clamp(P.ankRollP,-10.0,10.0);
  P.ankRollD = clamp(P.ankRollD,-6.0,6.0);
  P.ankRollC = clamp(P.ankRollC,-10.0,10.0);
  P.yawP = clamp(P.yawP,-5.0,5.0);
  P.yawD = clamp(P.yawD,-5.0,5.0);
  P.gaitAmp = clamp(P.gaitAmp,0.0,1.6);
  P.period = clamp(P.period,0.20,2.80);
  P.stanceFrac = clamp(P.stanceFrac,0.30,0.90);
  P.phaseOffset = clamp(P.phaseOffset,0.0,1.0);
  P.startTime = clamp(P.startTime,0.0,3.0);
  P.ramp = clamp(P.ramp,0.05,2.8);
  P.startPhase = clamp(P.startPhase,0.0,1.0);
  P.hipAmp = clamp(P.hipAmp,-0.4,1.6);
  P.gaitHipBias = clamp(P.gaitHipBias,-0.6,0.6);
  P.kneeSwing = clamp(P.kneeSwing,-0.2,2.0);
  P.kneeLand = clamp(P.kneeLand,-0.3,0.9);
  P.kneeStance = clamp(P.kneeStance,-0.4,0.7);
  P.kneePush = clamp(P.kneePush,-0.4,0.7);
  P.ankleSwing = clamp(P.ankleSwing,-0.8,0.9);
  P.ankleStance = clamp(P.ankleStance,-0.8,0.8);
  P.anklePush = clamp(P.anklePush,-0.8,0.8);
  P.outSwing = clamp(P.outSwing,-0.6,0.7);
  P.outStance = clamp(P.outStance,-0.5,0.5);
  P.latAmp = clamp(P.latAmp,-0.4,0.4);
  P.latPhase = clamp(P.latPhase,-6.5,6.5);
  P.armAmp = clamp(P.armAmp,0.0,1.4);
  P.armPhase = clamp(P.armPhase,-6.5,6.5);
  P.phaseP = clamp(P.phaseP,-4.0,4.0);
  P.phaseD = clamp(P.phaseD,-3.0,3.0);
  P.terrainKnee = clamp(P.terrainKnee,-4.0,6.0);
  P.terrainHip = clamp(P.terrainHip,-4.0,4.0);
  P.terrainAnkle = clamp(P.terrainAnkle,-4.0,4.0);
  P.terrainDownKnee = clamp(P.terrainDownKnee,-5.0,5.0);
  P.terrainDownHip = clamp(P.terrainDownHip,-4.0,4.0);
  P.terrainDownAnkle = clamp(P.terrainDownAnkle,-4.0,4.0);
  P.stumbleKnee = clamp(P.stumbleKnee,-2.0,2.0);
  P.stumbleHip = clamp(P.stumbleHip,-2.0,2.0);
  P.stumbleAnkle = clamp(P.stumbleAnkle,-2.0,2.0);
  P.contactThresh = clamp(P.contactThresh,0.01,0.80);
  P.safeP = clamp(P.safeP,0.10,1.5);
  P.safeR = clamp(P.safeR,0.10,1.5);
  P.safeGain = clamp(P.safeGain,0.0,15.0);
  P.recDamp = clamp(P.recDamp,0.0,1.3);
  P.recKnee = clamp(P.recKnee,-0.3,1.2);
  P.recOut = clamp(P.recOut,-0.2,0.7);
  P.recHip = clamp(P.recHip,-0.8,0.8);
  P.recAnkle = clamp(P.recAnkle,-0.8,0.8);
  P.recArm = clamp(P.recArm,0.0,1.2);
  P.airDamp = clamp(P.airDamp,0.0,1.4);
  P.split = clamp(P.split,-0.6,0.6);
  P.splitKnee = clamp(P.splitKnee,-0.7,1.0);
  P.splitAnkle = clamp(P.splitAnkle,-0.8,0.8);
  P.diveStart = clamp(P.diveStart,-1.0,9999.0);
  P.diveRamp = clamp(P.diveRamp,0.03,1.5);
  P.diveHip = clamp(P.diveHip,-2.0,2.0);
  P.diveKnee = clamp(P.diveKnee,-1.5,1.5);
  P.diveAnkle = clamp(P.diveAnkle,-2.0,2.0);
  P.diveWaist = clamp(P.diveWaist,-1.5,2.0);
  P.diveArm = clamp(P.diveArm,-2.0,2.5);
  P.diveOut = clamp(P.diveOut,-0.8,0.8);
  P.diveBal = clamp(P.diveBal,0.0,1.5);
  return P;
}

function policy(obs, params, mem){
  obs = obs || {};
  mem = mem || {};

  var P = mem._P;
  if (!P){
    P = normP(params);
    mem._P = P;
  }

  var t = num(obs.t,0);
  var ori = obs.orientation || [0,0,0];
  var gyro = obs.gyro || [0,0,0];
  var joints = obs.joints || [];
  var speeds = obs.speeds || [];
  var feet = obs.feet || [0,0];
  var ground = obs.ground || [];
  var j, leg;

  if (!mem.init){
    mem.init = true;
    mem.lastT = t;
    mem.estR = num(ori[0],0);
    mem.estP = num(ori[1],0);
    mem.estY = num(ori[2],0);
    mem.biasR = 0;
    mem.biasP = 0;
    mem.biasY = 0;
    mem.rateR = 0;
    mem.rateP = 0;
    mem.rateY = 0;
    mem.intP = 0;
    mem.intR = 0;
    mem.qF = [];
    mem.dqF = [];
    for (j=0;j<21;j++){
      mem.qF[j] = num(joints[j],0);
      mem.dqF[j] = num(speeds[j],0);
    }
    mem.fL = Math.max(0,num(feet[0],0));
    mem.fR = Math.max(0,num(feet[1],0));
    mem.maxLoad = Math.max(0.01,mem.fL+mem.fR);
    mem.phase = 0;
    mem.started = false;
    mem.rec = 0;
    mem.air = 0;
  }

  var dt = t - mem.lastT;
  if (!(dt > 0) || dt > 0.20) dt = 0.02;
  mem.lastT = t;

  var gR = num(gyro[0],0);
  var gP = num(gyro[1],0);
  var gY = num(gyro[2],0);
  var rawR = num(ori[0],mem.estR);
  var rawP = num(ori[1],mem.estP);
  var rawY = num(ori[2],mem.estY);

  mem.estR += (gR - mem.biasR)*dt;
  mem.estP += (gP - mem.biasP)*dt;
  mem.estY += (gY - mem.biasY)*dt;

  var errR = wrapPi(rawR - mem.estR);
  var errP = wrapPi(rawP - mem.estP);
  var errY = wrapPi(rawY - mem.estY);

  mem.estR += errR*0.022;
  mem.estP += errP*0.022;
  mem.estY += errY*0.010;
  mem.biasR += errR*0.000018;
  mem.biasP += errP*0.000018;
  mem.biasY += errY*0.000008;

  mem.rateR = 0.82*mem.rateR + 0.18*(gR - mem.biasR);
  mem.rateP = 0.82*mem.rateP + 0.18*(gP - mem.biasP);
  mem.rateY = 0.82*mem.rateY + 0.18*(gY - mem.biasY);

  for (j=0;j<21;j++){
    var qj = num(joints[j],mem.qF[j]);
    var dj = num(speeds[j],mem.dqF[j]);
    mem.qF[j] = 0.68*mem.qF[j] + 0.32*qj;
    mem.dqF[j] = 0.65*mem.dqF[j] + 0.35*dj;
  }

  var rawL = Math.max(0,num(feet[0],0));
  var rawR = Math.max(0,num(feet[1],0));
  mem.fL = 0.65*mem.fL + 0.35*rawL;
  mem.fR = 0.65*mem.fR + 0.35*rawR;
  var totalF = mem.fL + mem.fR;
  mem.maxLoad = Math.max(mem.maxLoad*0.9995,totalF,0.01);

  var wL, wR;
  if (totalF > 0.02){
    wL = clamp(mem.fL/(0.28*totalF+1e-6),0,1);
    wR = clamp(mem.fR/(0.28*totalF+1e-6),0,1);
  } else {
    wL = 0.5;
    wR = 0.5;
  }

  var airborne = (totalF < 0.045*mem.maxLoad) ? 1 : 0;
  mem.air = 0.90*mem.air + 0.10*airborne;

  var eP = mem.estP - P.pitchRef;
  var eR = mem.estR - P.rollRef;
  var eY = wrapPi(mem.estY - P.yawRef);

  mem.intP = clamp(mem.intP*0.995 + eP*dt,-1.0,1.0);
  mem.intR = clamp(mem.intR*0.995 + eR*dt,-1.0,1.0);

  var overP = Math.max(0,Math.abs(eP)-P.safeP);
  var overR = Math.max(0,Math.abs(eR)-P.safeR);
  var recWant = clamp((overP+overR)*P.safeGain,0,1);
  recWant = Math.max(recWant,mem.air*P.airDamp);
  mem.rec = 0.90*mem.rec + 0.10*recWant;

  var pose = smooth01(t/Math.max(0.05,P.poseTime));

  var dive = 0;
  if (P.diveStart < 100 && t >= P.diveStart){
    dive = smooth01((t-P.diveStart)/Math.max(0.03,P.diveRamp));
  }
  var balScale = clamp(1 - P.diveBal*dive,0,1);
  var recAmt = mem.rec*balScale;

  if (!mem.started && t >= P.startTime){
    mem.started = true;
    mem.phase = P.startPhase;
  }

  var ramp = 0;
  if (mem.started){
    var pSpeed = 1 + P.phaseP*eP + P.phaseD*mem.rateP;
    pSpeed = clamp(pSpeed,0.20,3.0);
    mem.phase = frac(mem.phase + dt/Math.max(0.15,P.period)*pSpeed);
    ramp = smooth01((t-P.startTime)/Math.max(0.05,P.ramp));
  }

  var g = P.gaitAmp*ramp;
  g *= (1 - P.recDamp*mem.rec);
  if (dive > 0) g *= clamp(1-0.7*dive,0,1);
  if (g < 0) g = 0;
  if (g > 1.6) g = 1.6;

  var sf = clamp(P.stanceFrac,0.30,0.90);
  var lat = P.latAmp*g*Math.sin(2*Math.PI*mem.phase + P.latPhase);

  var waistTarget = P.waist0*pose +
    (P.waistP*eP + P.waistD*mem.rateP + P.waistI*mem.intP)*balScale;

  var target = [];
  for (j=0;j<21;j++) target[j] = 0;
  target[0] = clamp(waistTarget + P.diveWaist*dive,LIMLO[0],LIMHI[0]);

  for (leg=0; leg<2; leg++){
    var bw0 = (leg===0) ? wL : wR;
    var bw = 0.15 + 0.85*bw0;

    var hip = P.hip0*pose;
    var knee = P.knee0*pose;
    var ankle = P.ankle0*pose;
    var out = P.out0*pose;
    var twist = P.twist0*pose;
    var ankleRoll = 0.0;

    if (P.split !== 0){
      if (leg === 0){
        hip += P.split;
        knee += P.splitKnee;
        ankle += P.splitAnkle;
      } else {
        hip -= P.split;
        knee += P.splitKnee;
        ankle -= P.splitAnkle;
      }
    }

    var ph = 0.0;
    var isSwing = false;
    var swingW = 0.0;
    var sw = 0.0;

    if (g > 1e-6){
      ph = frac(mem.phase + (leg===0 ? 0.0 : P.phaseOffset));
      isSwing = ph >= sf;
      if (!isSwing){
        var u = ph/Math.max(1e-6,sf);
        hip += g*(P.hipAmp*(1-2*u) + P.gaitHipBias);
        knee += g*(P.kneeLand*(1-u)*(1-u) +
                  P.kneeStance*Math.sin(Math.PI*u) +
                  P.kneePush*Math.sin(Math.PI*u));
        ankle += g*(P.ankleStance*(1-2*u) + P.anklePush*Math.sin(Math.PI*u));
        out += g*P.outStance*(1-2*u);
        swingW = 0.0;
      } else {
        swingW = clamp((ph-sf)/Math.max(1e-6,1-sf),0,1);
        sw = Math.sin(Math.PI*swingW);
        var sm = smooth01(swingW);
        hip += g*(P.hipAmp*(-1+2*sm) + P.gaitHipBias);
        knee += g*P.kneeSwing*sw;
        ankle += g*P.ankleSwing*sw;
        out += g*P.outSwing*sw;
      }
      out += lat*(leg===0 ? 1 : -1);
    } else {
      hip += g*P.gaitHipBias;
    }

    var aCorr = (P.ankP*eP + P.ankD*mem.rateP + P.ankI*mem.intP)*bw*balScale;
    ankle += aCorr;

    var hCorr = (P.hipP*eP + P.hipD*mem.rateP + P.hipI*mem.intP)*bw*balScale;
    hip += hCorr;

    knee += (P.kneeP*eP + P.kneeD*mem.rateP)*bw*balScale;

    var oCorr = (P.outP*eR + P.outD*mem.rateR + P.outI*mem.intR)*bw*balScale;
    out += oCorr*(leg===0 ? 1 : -1);

    var ar = (P.ankRollP*eR + P.ankRollD*mem.rateR)*bw*balScale;
    ankleRoll += ar*(leg===0 ? 1 : -1) + P.ankRollC*eR*bw*balScale;

    twist += (P.yawP*eY + P.yawD*mem.rateY)*bw*balScale*(leg===0 ? 1 : -1);

    knee += P.recKnee*recAmt;
    out += P.recOut*recAmt;
    hip += P.recHip*recAmt;
    ankle += P.recAnkle*recAmt;

    if (g > 0.02 && isSwing && ground.length >= 18){
      var c = (leg===0) ? 0 : 2;
      var h0 = num(ground[c],0);
      var h1 = num(ground[3+c],0);
      var h2 = num(ground[6+c],0);
      var h3 = num(ground[9+c],0);
      var hc0 = num(ground[1],0);
      var hc1 = num(ground[4],0);
      var up = Math.max(0,h0,h1*0.80,h2*0.60,h3*0.40,hc0*0.50,hc1*0.30);
      var dn = Math.min(0,h0,h1*0.80,h2*0.60,h3*0.40,hc0*0.50,hc1*0.30);
      var lift = Math.max(0.12,sw);
      knee += (P.terrainKnee*up + P.terrainDownKnee*dn)*lift;
      hip += (P.terrainHip*up + P.terrainDownHip*dn)*lift;
      ankle += (P.terrainAnkle*up + P.terrainDownAnkle*dn)*lift;
    }

    if (g > 0.02 && isSwing){
      var fHit = (leg===0) ? mem.fL : mem.fR;
      var fTot = Math.max(0.02,mem.fL+mem.fR);
      var cHit = clamp((fHit - P.contactThresh*fTot)/(0.15*fTot+1e-6),0,1);
      if (cHit > 0.03 && swingW < 0.92){
        var st = cHit*(1-swingW);
        knee += P.stumbleKnee*st;
        hip += P.stumbleHip*st;
        ankle += P.stumbleAnkle*st;
      }
    }

    if (dive > 0){
      hip += P.diveHip*dive;
      knee += P.diveKnee*dive;
      ankle += P.diveAnkle*dive;
      out += P.diveOut*dive;
    }

    var b = (leg===0) ? 1 : 11;
    target[b] = clamp(hip,LIMLO[b],LIMHI[b]);
    target[b+1] = clamp(out,LIMLO[b+1],LIMHI[b+1]);
    target[b+2] = clamp(twist,LIMLO[b+2],LIMHI[b+2]);
    target[b+3] = clamp(knee,LIMLO[b+3],LIMHI[b+3]);
    target[b+4] = clamp(ankle,LIMLO[b+4],LIMHI[b+4]);
    target[b+5] = clamp(ankleRoll,LIMLO[b+5],LIMHI[b+5]);
  }

  var armSwing = P.armAmp*g;
  var cosArm = Math.cos(2*Math.PI*(mem.phase+P.armPhase));
  var armL = P.armFwd0*pose - armSwing*cosArm;
  var armR = P.armFwd0*pose + armSwing*cosArm;
  var armPitch = (P.armPitchP*eP + P.armPitchD*mem.rateP)*balScale;
  armL += armPitch;
  armR += armPitch;

  var shBase = P.armOut0*pose + P.recArm*recAmt;
  var armRoll = (P.armRollP*eR + P.armRollD*mem.rateR)*balScale;
  var shL = shBase + armRoll;
  var shR = shBase - armRoll;
  var elbow = P.elbow0*pose;

  if (dive > 0){
    armL += P.diveArm*dive;
    armR += P.diveArm*dive;
    shL += 0.35*P.diveArm*dive;
    shR += 0.35*P.diveArm*dive;
  }

  target[7] = clamp(armL,LIMLO[7],LIMHI[7]);
  target[8] = clamp(shL,LIMLO[8],LIMHI[8]);
  target[9] = 0;
  target[10] = clamp(elbow,LIMLO[10],LIMHI[10]);
  target[17] = clamp(armR,LIMLO[17],LIMHI[17]);
  target[18] = clamp(shR,LIMLO[18],LIMHI[18]);
  target[19] = 0;
  target[20] = clamp(elbow,LIMLO[20],LIMHI[20]);

  var cmd = [];
  for (j=0;j<21;j++){
    var tv = target[j];
    if (!isFinite(tv)) tv = 0;
    tv = clamp(tv,LIMLO[j],LIMHI[j]);
    var isArm = ((j>=7 && j<=10) || (j>=17 && j<=20));
    var kpj = isArm ? P.kpArm : P.kp;
    var kvj = isArm ? P.kdArm : P.kd;
    var cval = kpj*KPJ[j]*(tv - mem.qF[j]) - kvj*KDJ[j]*mem.dqF[j];
    if (!isFinite(cval)) cval = 0;
    cmd[j] = clamp(cval,-1,1);
  }
  return cmd;
}

function learn(lab){
  var used = 0;
  var cache = {};
  var all = [];
  var standPool = [];
  var gaitPool = [];

  function has(o,k){
    return Object.prototype.hasOwnProperty.call(o,k);
  }
  function copy(o){
    var r = {};
    var k;
    if (!o) return r;
    for (k in o){
      if (has(o,k)) r[k] = o[k];
    }
    return r;
  }
  function fill(par){
    var o = {};
    var k;
    for (k in DEF){
      if (has(DEF,k)) o[k] = DEF[k];
    }
    if (par && typeof par === "object"){
      for (k in DEF){
        if (has(DEF,k) && par[k] !== undefined){
          var v = Number(par[k]);
          if (isFinite(v)) o[k] = v;
        }
      }
    }
    return o;
  }
  function mk(over,base){
    var o = base ? copy(base) : fill(DEF);
    var k;
    if (over){
      for (k in over){
        if (has(over,k)) o[k] = over[k];
      }
    }
    return fill(o);
  }
  function getTrialsLeft(){
    try {
      var x = lab.trialsLeft();
      if (x === undefined || x === null || !isFinite(x)) return 1000;
      return x;
    } catch(e) {
      return 1000;
    }
  }
  function getTimeLeft(){
    try {
      var x = lab.timeLeft();
      if (x === undefined || x === null || !isFinite(x)) return 1000;
      return x;
    } catch(e) {
      return 1000;
    }
  }
  function canTrial(){
    return used < 200 && getTrialsLeft() > 0 && getTimeLeft() > 0.65;
  }
  function randn(){
    var u1 = 0, u2 = 0;
    while (u1 === 0) u1 = Math.random();
    while (u2 === 0) u2 = Math.random();
    return Math.sqrt(-2*Math.log(u1))*Math.cos(2*Math.PI*u2);
  }

  function stats(r){
    var inv = (!r ||
      r.outcome === "invalid" ||
      r.outcome === "error" ||
      r.outcome === "exploit");
    var d = r ? Number(r.distance) : 0;
    if (!isFinite(d)) d = 0;
    var tm = r ? Number(r.time) : 0;
    if (!isFinite(tm)) tm = 0;
    var fin = (r && r.outcome === "finished") || tm >= 9.75;
    var en = r ? Number(r.energy) : 0;
    if (!isFinite(en)) en = 0;

    var tr = (r && r.trace && r.trace.length) ? r.trace : [];
    var h0 = 1.0;
    var i;
    if (tr.length > 0 && tr[0] && tr[0].length >= 3){
      var hh = Math.abs(num(tr[0][2],0));
      if (hh > 0.05) h0 = hh;
    }

    var rows = [];
    var minR = 1e9;
    var maxRoll = 0;
    var maxPitch = 0;
    var maxSide = 0;
    var last = null;

    for (i=0;i<tr.length;i++){
      var row = tr[i];
      if (!row || row.length < 6) continue;
      var tt = num(row[0],0);
      var dd = num(row[1],0);
      var hh2 = Math.abs(num(row[2],h0));
      var side = Math.abs(num(row[3],0));
      var rr = Math.abs(num(row[4],0));
      var pp = Math.abs(num(row[5],0));
      var ratio = hh2/h0;
      if (ratio < minR) minR = ratio;
      if (side > maxSide) maxSide = side;
      if (rr > maxRoll) maxRoll = rr;
      if (pp > maxPitch) maxPitch = pp;
      rows.push({t:tt,d:dd,h:ratio,side:side,roll:rr,pitch:pp});
      last = row;
    }
    if (minR > 1e8) minR = 1.0;

    var finalR = 1.0;
    var finalSide = 0.0;
    var finalRoll = 0.0;
    var finalPitch = 0.0;
    if (last){
      finalR = Math.abs(num(last[2],h0))/h0;
      finalSide = Math.abs(num(last[3],0));
      finalRoll = Math.abs(num(last[4],0));
      finalPitch = Math.abs(num(last[5],0));
    }

    return {
      inv:inv, dist:d, time:tm, finished:fin, energy:Math.abs(en),
      h0:h0, rows:rows, minR:minR,
      maxRoll:maxRoll, maxPitch:maxPitch, maxSide:maxSide,
      finalR:finalR, finalSide:finalSide, finalRoll:finalRoll, finalPitch:finalPitch
    };
  }

  function isStandStable(m){
    return !m.inv && m.finished && m.time > 9.40 &&
      m.minR > 0.56 && m.finalR > 0.62 &&
      m.maxRoll < 0.78 && m.maxPitch < 0.88 &&
      m.maxSide < 1.70 &&
      m.finalRoll < 0.55 && m.finalPitch < 0.68;
  }
  function isSafeGait(m){
    return !m.inv && m.finished && m.time > 9.40 &&
      m.minR > 0.52 && m.finalR > 0.58 &&
      m.maxRoll < 0.92 && m.maxPitch < 1.05 &&
      m.maxSide < 1.85 &&
      m.finalRoll < 0.65 && m.finalPitch < 0.82;
  }
  function isUltra(m){
    return !m.inv && m.finished && m.time > 9.60 &&
      m.minR > 0.63 && m.finalR > 0.68 &&
      m.maxRoll < 0.68 && m.maxPitch < 0.78 &&
      m.maxSide < 1.35;
  }

  function standScore(m){
    if (m.inv) return -1e18;
    var s = 0;
    if (m.finished) s += 1e10;
    s += Math.min(10,m.time)*1e6;
    s += m.minR*2.0e5 + m.finalR*1.0e5;
    s -= Math.max(0,m.maxRoll-0.35)*3.0e5;
    s -= Math.max(0,m.maxPitch-0.45)*3.0e5;
    s -= Math.max(0,m.maxSide-0.50)*2.0e5;
    s -= Math.max(0,0.70-m.finalR)*4.0e5;
    s -= m.finalRoll*5.0e4 + m.finalPitch*5.0e4;
    s -= Math.abs(m.dist)*1000;
    return s;
  }

  function gaitScore(m){
    if (m.inv) return -1e18;
    var s = m.dist*1.0e6 + Math.min(10,m.time)*1.0e5;
    if (m.finished) s += 5.0e8;
    if (isSafeGait(m)) s += 2.0e9;
    if (isUltra(m)) s += 5.0e8;
    s += m.minR*1.0e6 + m.finalR*5.0e5;
    s -= Math.max(0,m.maxRoll-0.80)*2.0e7;
    s -= Math.max(0,m.maxPitch-0.90)*2.0e7;
    s -= Math.max(0,m.maxSide-1.50)*1.0e7;
    s -= Math.max(0,0.60-m.minR)*2.0e7;
    if (m.finished){
      s -= Math.max(0,0.65-m.finalR)*2.0e7;
      s -= Math.max(0,m.finalRoll-0.60)*1.0e7;
      s -= Math.max(0,m.finalPitch-0.85)*1.0e7;
    } else {
      s -= (10-m.time)*1.0e4;
    }
    return s;
  }

  function fallbackScore(r){
    if (!r || r.m.inv) return -1e18;
    var m = r.m;
    var s = m.dist*20.0 + Math.min(10,m.time);
    if (m.finished) s += 5.0;
    s -= Math.max(0,m.maxRoll-1.0)*10.0;
    s -= Math.max(0,m.maxPitch-1.2)*10.0;
    s -= Math.max(0,0.5-m.minR)*10.0;
