  }

  function addRec(rec){
    all.push(rec);
    if (rec.m.inv) return;

    if (rec.p.gaitAmp <= 0.02){
      standPool.push(rec);
      standPool.sort(function(a,b){ return b.stand - a.stand; });
      if (standPool.length > 70) standPool.length = 70;
    } else {
