    }
    used++;
    var m = stats(r);
    var rec = {
      p:p, m:m, tag:tag,
      stand:standScore(m),
      gait:gaitScore(m),
      safe:isSafeGait(m),
      ultra:isUltra(m)
    };
    cache[key] = rec;
    addRec(rec);
    return rec;
  }

  var SPEC = [
