      } else {
        standNo++;
        standScale = Math.min(1.55,standScale*1.005);
      }
    }
    if (standNo > 10){
      standNo = 0;
      standScale = Math.min(1.85,standScale*1.30);
      if (canTrial()){
        var rs = mutatePar(base,1.15,standFocus);
        rs.gaitAmp = 0.0;
        rs.diveStart = 999.0;
        evalP(rs,"standrestart","stand");
      }
    }
  }

  var baseLoc;
  if (standPool.length > 0) baseLoc = copy(standPool[0].p);
  else baseLoc = copy(base);

  var amps = [0.035,0.070,0.120,0.200,0.300,0.420];
  var periods = [0.80,0.95,1.15,1.40,1.70];
  var stances = [0.58,0.65,0.72];

  var ii;
  for (ii=0; ii<26 && canTrial(); ii++){
    var gp;
    if (ii%5 === 0 && standPool.length > 4){
      gp = copy(standPool[ii%Math.min(6,standPool.length)].p);
    } else {
      gp = copy(baseLoc);
    }
    gp.gaitAmp = amps[ii%amps.length];
    gp.period = periods[(ii+1)%periods.length];
    gp.stanceFrac = stances[(ii+2)%stances.length];
    gp.phaseOffset = 0.50;
    gp.startTime = 0.70 + 0.10*(ii%3);
    gp.ramp = 0.85 + 0.05*(ii%4);
    gp.startPhase = 0.0;
    gp.hipAmp = 0.28 + 0.08*((ii>>1)%4);
    gp.gaitHipBias = 0.0;
    gp.kneeSwing = 0.42 + 0.09*((ii>>1)%5);
    gp.kneeLand = 0.045 + 0.018*(ii%3);
    gp.kneeStance = 0.025;
    gp.kneePush = 0.025;
    gp.ankleSwing = 0.07 + 0.02*(ii%3);
    gp.ankleStance = 0.06;
    gp.anklePush = 0.025 + 0.01*(ii%2);
    gp.outSwing = 0.015 + 0.010*(ii%3);
    gp.outStance = 0.0;
    gp.latAmp = -0.030 + 0.012*(ii%5);
    gp.latPhase = 0.0;
    gp.armAmp = 0.10 + 0.035*(ii%4);
    gp.safeGain = Math.max(2.0,gp.safeGain);
    gp.recDamp = 0.75;
    gp.diveStart = 999.0;
    evalP(gp,"gaitseed","gait");
  }

  var gaitScale = 0.90;
  var gaitNo = 0;
  var bestGaitSeen = -1e18;
  if (gaitPool.length > 0) bestGaitSeen = gaitPool[0].gait;

  while (used < 168 && canTrial()){
    var gParent;
    if (gaitPool.length > 0 && Math.random() < 0.86){
      var idxG = Math.floor(Math.random()*Math.min(gaitPool.length,14));
      if (Math.random() < 0.30) idxG = 0;
      gParent = gaitPool[Math.min(idxG,gaitPool.length-1)].p;
    } else if (standPool.length > 0){
      gParent = standPool[Math.floor(Math.random()*Math.min(standPool.length,8))].p;
    } else {
      gParent = baseLoc;
    }

    var focus;
    var rr = Math.random();
    if (rr < 0.55) focus = gaitFocus;
    else if (rr < 0.85) focus = balanceFocus;
    else focus = terrainFocus;

    var gChild = mutatePar(gParent,gaitScale,focus);
    gChild.diveStart = 999.0;

    if (gChild.gaitAmp < 0.02 && Math.random() < 0.75){
      gChild.gaitAmp = 0.02 + Math.random()*0.30;
    }
    if (Math.random() < 0.055){
      gChild.gaitAmp = 0.04 + Math.random()*0.55;
      gChild.period = 0.55 + Math.random()*1.20;
      gChild.stanceFrac = 0.55 + Math.random()*0.24;
      gChild.phaseOffset = 0.50;
      gChild.startTime = 0.55 + Math.random()*0.60;
      gChild.hipAmp = 0.28 + Math.random()*0.40;
      gChild.kneeSwing = 0.40 + Math.random()*0.55;
      gChild.ankleSwing = 0.05 + Math.random()*0.16;
    }

    var gRec = evalP(gChild,"gaitevo","gait");
    if (gRec){
      if (gRec.gait > bestGaitSeen + 1e-9){
        bestGaitSeen = gRec.gait;
        gaitNo = 0;
        gaitScale = Math.max(0.22,gaitScale*0.90);
      } else {
        gaitNo++;
        gaitScale = Math.min(1.70,gaitScale*1.005);
      }
    }

    if (gaitNo > 12){
      gaitNo = 0;
      gaitScale = Math.min(1.90,gaitScale*1.25);
      if (canTrial()){
        var kick = mutatePar(baseLoc,1.20,gaitFocus);
        kick.gaitAmp = 0.06 + Math.random()*0.55;
        kick.period = 0.55 + Math.random()*1.10;
        kick.stanceFrac = 0.55 + Math.random()*0.22;
        kick.phaseOffset = 0.50;
        kick.diveStart = 999.0;
        evalP(kick,"kick","gait");
      }
    }
  }

  var valCands = [];
  var vi;
  for (vi=0; vi<gaitPool.length && valCands.length<9; vi++){
    if (gaitPool[vi].m.finished || gaitPool[vi].m.time > 5.5){
      valCands.push(copy(gaitPool[vi].p));
    }
  }

  for (vi=0; vi<valCands.length && used < 182 && canTrial(); vi++){
    var cand = valCands[vi];

    var v1 = copy(cand);
    v1.gaitAmp *= 0.78;
    if (v1.gaitAmp < 0.02) v1.gaitAmp = 0.02;
    v1.safeGain = Math.min(12.0,v1.safeGain*1.15);
    v1.recDamp = Math.min(1.2,v1.recDamp*1.10);
    v1.period = Math.min(2.6,v1.period*1.03);
    v1.diveStart = 999.0;
    evalP(v1,"val78","gait");

    if (used < 182 && canTrial()){
      var v2 = copy(cand);
      v2.gaitAmp *= 0.60;
      if (v2.gaitAmp < 0.02) v2.gaitAmp = 0.02;
      v2.safeGain = Math.min(12.0,v2.safeGain*1.30);
      v2.recDamp = Math.min(1.2,v2.recDamp*1.18);
      v2.stanceFrac = Math.min(0.88,v2.stanceFrac*1.03);
      v2.diveStart = 999.0;
      evalP(v2,"val60","gait");
    }
  }

  function pickFinalRec(){
    var i;
    var bestSafe = null;
    for (i=0;i<gaitPool.length;i++){
      var r = gaitPool[i];
      if (r.p.gaitAmp > 0.025 && r.safe && r.m.dist > 0.04){
        if (!bestSafe || r.m.dist > bestSafe.m.dist) bestSafe = r;
      }
    }
    if (bestSafe) return bestSafe;

    for (i=0;i<gaitPool.length;i++){
      var r2 = gaitPool[i];
      if (r2.p.gaitAmp > 0.025 && isSafeGait(r2.m) && r2.m.dist > -0.02){
        if (!bestSafe || r2.gait > bestSafe.gait) bestSafe = r2;
      }
    }
    if (bestSafe) return bestSafe;

    var bestStand = null;
    for (i=0;i<standPool.length;i++){
      if (isStandStable(standPool[i].m)){
        bestStand = standPool[i];
        break;
      }
    }
    if (bestStand) return bestStand;

    if (standPool.length > 0 && standPool[0].m.time > 5.5){
      return standPool[0];
    }

    var best = null;
    var bs = -1e18;
    for (i=0;i<all.length;i++){
      var s = fallbackScore(all[i]);
      if (s > bs){
        bs = s;
        best = all[i];
      }
    }
    return best;
  }

  var chosenRec = pickFinalRec();
  var finalP;
  if (chosenRec) finalP = copy(chosenRec.p);
  else finalP = copy(base);

  var chosenDive = null;
  var bestDiveGain = -1e18;

  if (chosenRec && canTrial()){
    var startTrain = 1.5;
    var horizon = 1.2;
    var baseline = distanceAt(chosenRec.m,startTrain + horizon);
    if (baseline < -1e8) baseline = 0;

    var diveGrid = [
      {ramp:0.25,hip:-0.40,knee:-0.30,ankle:-0.50,waist:0.50,arm:0.40,out:0.00,bal:0.80},
      {ramp:0.20,hip:-0.70,knee:-0.50,ankle:-0.70,waist:0.70,arm:0.70,out:0.05,bal:0.90},
      {ramp:0.35,hip:-0.20,knee:0.00,ankle:-0.60,waist:0.40,arm:0.20,out:0.00,bal:0.50},
      {ramp:0.25,hip:0.30,knee:0.10,ankle:-0.50,waist:0.60,arm:0.50,out:0.00,bal:0.80},
      {ramp:0.25,hip:-0.50,knee:-0.40,ankle:0.40,waist:0.30,arm:0.30,out:0.00,bal:0.70},
      {ramp:0.25,hip:-0.30,knee:-0.20,ankle:-0.80,waist:0.80,arm:0.80,out:0.10,bal:1.00},
      {ramp:0.15,hip:-1.00,knee:-0.60,ankle:-0.60,waist:1.00,arm:1.00,out:0.00,bal:1.20},
      {ramp:0.30,hip:0.60,knee:-0.20,ankle:-0.30,waist:0.30,arm:0.20,out:0.00,bal:0.60}
    ];

    var di;
    for (di=0; di<diveGrid.length && used < 198 && canTrial(); di++){
      var dp = copy(finalP);
      dp.diveStart = startTrain;
      dp.diveRamp = diveGrid[di].ramp;
      dp.diveHip = diveGrid[di].hip;
      dp.diveKnee = diveGrid[di].knee;
      dp.diveAnkle = diveGrid[di].ankle;
      dp.diveWaist = diveGrid[di].waist;
      dp.diveArm = diveGrid[di].arm;
      dp.diveOut = diveGrid[di].out;
      dp.diveBal = diveGrid[di].bal;

      var dRec = evalP(dp,"dive","any");
      if (dRec && !dRec.m.inv){
        var d1 = distanceAt(dRec.m,startTrain + horizon);
        var gain = d1 - baseline;
        if (gain > bestDiveGain){
          bestDiveGain = gain;
          chosenDive = dRec;
        }
      }
    }
  }

  if (chosenDive && bestDiveGain > 0.04){
    var out = copy(chosenDive.p);
    out.diveStart = 18.8;
    out.diveRamp = chosenDive.p.diveRamp;
    out.diveHip = chosenDive.p.diveHip;
    out.diveKnee = chosenDive.p.diveKnee;
    out.diveAnkle = chosenDive.p.diveAnkle;
    out.diveWaist = chosenDive.p.diveWaist;
    out.diveArm = chosenDive.p.diveArm;
    out.diveOut = chosenDive.p.diveOut;
    out.diveBal = chosenDive.p.diveBal;
    return fill(out);
  }

  var outFinal = copy(finalP);
  outFinal.diveStart = 999.0;
  return fill(outFinal);
}

