function clamp(x,a,b){
  x = Number(x);
  if (!isFinite(x)) return a;
  if (x < a) return a;
  if (x > b) return b;
  return x;
}
function num(x,d){
  x = Number(x);
  return isFinite(x) ? x : d;
}
function smooth01(x){
  x = clamp(x,0,1);
  return x*x*(3-2*x);
}
function frac(x){
  x = x - Math.floor(x);
  return x < 0 ? x + 1 : x;
}
function wrapPi(x){
  while (x > Math.PI) x -= 2*Math.PI;
  while (x < -Math.PI) x += 2*Math.PI;
  return x;
}
function hasOwn(o,k){
  return Object.prototype.hasOwnProperty.call(o,k);
}

function normP(params){
