      if (hasOwn(DEF,k) && params[k] !== undefined){
        var v = Number(params[k]);
        if (isFinite(v)) P[k] = v;
      }
    }
  }

  P.poseTime = clamp(P.poseTime,0.05,1.5);
  P.kp = clamp(P.kp,0.3,16.0);
  P.kd = clamp(P.kd,0.0,2.5);
