  P.diveAnkle = clamp(P.diveAnkle,-2.0,2.0);
  P.diveWaist = clamp(P.diveWaist,-1.5,2.0);
  P.diveOut = clamp(P.diveOut,-0.8,0.8);
  P.diveArm = clamp(P.diveArm,-2.0,2.5);
  P.diveBal = clamp(P.diveBal,0.0,1.5);

  return P;
}

function policy(obs, params, mem){
  obs = obs || {};
  mem = mem || {};

  var P = mem._P;
  if (!P){
    P = normP(params);
    mem._P = P;
  }

  var t = num(obs.t,0);
  var ori = obs.orientation || [0,0,0];
  var gyro = obs.gyro || [0,0,0];
  var joints = obs.joints || [];
  var speeds = obs.speeds || [];
  var feet = obs.feet || [0,0];
  var ground = obs.ground || [];
  var j, leg;

  if (!mem.init){
    mem.init = true;
    mem.lastT = t;
    mem.estR = num(ori[0],0);
    mem.estP = num(ori[1],0);
    mem.estY = num(ori[2],0);
    mem.lastRawR = mem.estR;
    mem.lastRawP = mem.estP;
    mem.lastRawY = mem.estY;
    mem.rateR = 0;
    mem.rateP = 0;
    mem.rateY = 0;
    mem.intP = 0;
    mem.intR = 0;
    mem.qF = [];
    mem.dqF = [];
    for (j=0;j<21;j++){
      mem.qF[j] = num(joints[j],0);
      mem.dqF[j] = num(speeds[j],0);
    }
    mem.fL = Math.max(0,num(feet[0],0));
    mem.fR = Math.max(0,num(feet[1],0));
    mem.maxLoad = Math.max(0.02,mem.fL+mem.fR);
    mem.cL = 0.5;
    mem.cR = 0.5;
    mem.phase = 0;
    mem.started = false;
    mem.rec = 0;
    mem.air = 0;
  }

  var dt = t - mem.lastT;
  if (!(dt > 0) || dt > 0.20) dt = 0.02;
  mem.lastT = t;

  var rawR = num(ori[0],mem.estR);
  var rawP = num(ori[1],mem.estP);
  var rawY = num(ori[2],mem.estY);
  var gR = num(gyro[0],0);
  var gP = num(gyro[1],0);
  var gY = num(gyro[2],0);

  mem.estR += gR*dt;
  mem.estP += gP*dt;
  mem.estY += gY*dt;
  mem.estR += wrapPi(rawR-mem.estR)*0.060;
  mem.estP += wrapPi(rawP-mem.estP)*0.060;
  mem.estY += wrapPi(rawY-mem.estY)*0.030;

  var dR = (rawR-mem.lastRawR)/Math.max(dt,1e-3);
  var dP = (rawP-mem.lastRawP)/Math.max(dt,1e-3);
  var dY = (rawY-mem.lastRawY)/Math.max(dt,1e-3);
  mem.lastRawR = rawR;
  mem.lastRawP = rawP;
  mem.lastRawY = rawY;

  mem.rateR = 0.78*mem.rateR + 0.22*(0.70*gR + 0.30*dR);
  mem.rateP = 0.78*mem.rateP + 0.22*(0.70*gP + 0.30*dP);
  mem.rateY = 0.78*mem.rateY + 0.22*(0.70*gY + 0.30*dY);

  for (j=0;j<21;j++){
    var qj = num(joints[j],mem.qF[j]);
    var dj = num(speeds[j],mem.dqF[j]);
    mem.qF[j] = 0.70*mem.qF[j] + 0.30*qj;
    mem.dqF[j] = 0.65*mem.dqF[j] + 0.35*dj;
  }

  var rawFL = Math.max(0,num(feet[0],0));
  var rawFR = Math.max(0,num(feet[1],0));
  mem.fL = 0.65*mem.fL + 0.35*rawFL;
  mem.fR = 0.65*mem.fR + 0.35*rawFR;
  var totalF = mem.fL + mem.fR;
  mem.maxLoad = Math.max(mem.maxLoad*0.9995,totalF,0.02);

  var cLtarget = smooth01(clamp((mem.fL-0.04*mem.maxLoad)/(0.25*mem.maxLoad+1e-6),0,1));
  var cRtarget = smooth01(clamp((mem.fR-0.04*mem.maxLoad)/(0.25*mem.maxLoad+1e-6),0,1));
  mem.cL = 0.75*mem.cL + 0.25*cLtarget;
  mem.cR = 0.75*mem.cR + 0.25*cRtarget;

  var airNow = (mem.fL < 0.07*mem.maxLoad && mem.fR < 0.07*mem.maxLoad) ? 1 : 0;
  mem.air = 0.90*mem.air + 0.10*airNow;

  var eP = mem.estP - P.pitchRef;
  var eR = mem.estR - P.rollRef;
  var eY = wrapPi(mem.estY - P.yawRef);

  mem.intP = clamp(mem.intP*0.995 + eP*dt,-1.0,1.0);
  mem.intR = clamp(mem.intR*0.995 + eR*dt,-1.0,1.0);

  var overP = Math.max(0,Math.abs(eP)-P.safeP);
  var overR = Math.max(0,Math.abs(eR)-P.safeR);
  var recWant = clamp((overP+overR)*P.safeGain,0,1);
  recWant = Math.max(recWant,mem.air*P.airDamp);
  mem.rec = 0.90*mem.rec + 0.10*recWant;

  var pose = smooth01(t/Math.max(0.05,P.poseTime));
  var stop = 0;
  if (t >= P.stopTime){
    stop = smooth01((t-P.stopTime)/Math.max(0.05,P.stopRamp));
  }
  var dive = 0;
  if (P.diveStart < 100 && t >= P.diveStart){
    dive = smooth01((t-P.diveStart)/Math.max(0.03,P.diveRamp));
  }
  var bal = clamp(1 - P.diveBal*dive,0,1);
  var recAmt = mem.rec;

  var sf = clamp(P.stanceFrac,0.30,0.90);
  if (!mem.started && t >= P.startTime){
    mem.started = true;
    mem.phase = P.startPhase;
  }

  var ramp = 0;
  if (mem.started){
    var pSpeed = 1 + P.phaseP*eP + P.phaseD*mem.rateP;
    pSpeed = clamp(pSpeed,0.18,3.0);

    var phL0 = frac(mem.phase);
    var phR0 = frac(mem.phase + P.phaseOffset);
    var wait = 0;
    if (phL0 >= sf && phR0 < sf && mem.fL > 0.52*mem.fR && mem.fL > 0.12*mem.maxLoad){
      wait = clamp((mem.fL-0.52*mem.fR)/(0.45*mem.maxLoad+1e-6),0,1);
    }
    if (phR0 >= sf && phL0 < sf && mem.fR > 0.52*mem.fL && mem.fR > 0.12*mem.maxLoad){
      wait = Math.max(wait,clamp((mem.fR-0.52*mem.fL)/(0.45*mem.maxLoad+1e-6),0,1));
    }
    pSpeed *= clamp(1-P.waitGain*wait,0.15,1.0);

    mem.phase = frac(mem.phase + dt/Math.max(0.15,P.period)*pSpeed);
    ramp = smooth01((t-P.startTime)/Math.max(0.05,P.ramp));
  }

  var active = ramp*(1-stop);
  var latActive = active * (P.gaitAmp > 0.01 ? 1 : 0);
  var latDes = P.latAmp*Math.cos(2*Math.PI*(mem.phase+P.latPhase))*latActive;
  var loadDiff = (mem.fR-mem.fL)/(totalF+1e-6);
  var sideDes = Math.cos(2*Math.PI*(mem.phase+P.latPhase));
  latDes += P.loadP*(sideDes-loadDiff)*latActive;
  var eRbal = mem.estR - P.rollRef - latDes;

  var gA = P.gaitAmp*ramp*(1-P.recDamp*recAmt)*(1-stop);
  if (dive > 0) gA *= clamp(1-0.55*dive,0,1);
  if (gA < 0) gA = 0;
  if (gA > 1.8) gA = 1.8;

  var target = [];
  for (j=0;j<21;j++) target[j] = 0;

  var waist = P.waist0*pose +
    (P.waistP*eP + P.waistD*mem.rateP + P.waistI*mem.intP)*bal +
    P.diveWaist*dive;
  target[0] = clamp(waist,LIMLO[0],LIMHI[0]);

  for (leg=0; leg<2; leg++){
    var isLeft = (leg === 0);
    var selfF = isLeft ? mem.fL : mem.fR;
    var oppF = isLeft ? mem.fR : mem.fL;
    var contactW = isLeft ? mem.cL : mem.cR;
    var bw = 0.18 + 0.82*contactW;
    var sgn = isLeft ? 1 : -1;

    var hip = P.hip0*pose + (isLeft ? P.split : -P.split);
    var knee = P.knee0*pose;
    var ankle = P.ankle0*pose;
    var out = P.out0*pose;
    var twist = 0;
    var roll = 0;
    var swingAmt = 0;

    if (gA > 1e-7){
      var ph = frac(mem.phase + (isLeft ? 0 : P.phaseOffset));
      if (ph < sf){
        var u = ph/Math.max(1e-6,sf);
        var swu = Math.sin(Math.PI*u);
        hip += gA*P.hipAmp*(1-2*u);
        knee += gA*(P.kneeLand*(1-u)*(1-u) + P.kneeStance*swu + P.kneePush*swu);
        ankle += gA*(P.ankleStance*(1-2*u) - P.anklePush*Math.max(0,2*u-1));
        out += gA*P.outStance*(1-2*u);
      } else {
        var w = (ph-sf)/Math.max(1e-6,1-sf);
        var sw = Math.sin(Math.PI*clamp(w,0,1));
        var lr = (oppF-selfF)/(0.35*mem.maxLoad+1e-6);
        var gate = smooth01(0.50+lr);
        gate = 0.15 + 0.85*gate;
        swingAmt = sw*gate;
        var sm = smooth01(w);
        hip += gA*P.hipAmp*(-1+2*sm)*gate;
        knee += gA*P.kneeSwing*sw*gate;
        ankle += gA*P.ankleSwing*sw*gate;
        out += gA*P.outSwing*sw*gate;

        if (ground.length >= 18){
          var c = isLeft ? 0 : 2;
          var gh0 = num(ground[c],0);
          var gh1 = num(ground[3+c],0);
          var gh2 = num(ground[6+c],0);
          var gh3 = num(ground[9+c],0);
          var ghc0 = num(ground[1],0);
          var ghc1 = num(ground[4],0);
          var up = Math.max(0,gh0,gh1*0.80,gh2*0.60,gh3*0.40,ghc0*0.50,ghc1*0.30);
          var dn = Math.min(0,gh0,gh1*0.80,gh2*0.60,gh3*0.40,ghc0*0.50,ghc1*0.30);
          var lift = Math.max(0.12,swingAmt);
          knee += (P.terrainKnee*up + P.terrainDownKnee*dn)*lift;
          hip += (P.terrainHip*up + P.terrainDownHip*dn)*lift;
          ankle += (P.terrainAnkle*up + P.terrainDownAnkle*dn)*lift;
        }

        var cHit = clamp((selfF-P.contactThresh*mem.maxLoad)/(0.20*mem.maxLoad+1e-6),0,1);
        if (cHit > 0.03 && w < 0.92){
          var st = cHit*(1-w);
          knee += P.stumbleKnee*st;
          hip += P.stumbleHip*st;
          ankle += P.stumbleAnkle*st;
        }
      }
    }

    ankle += (P.ankP*eP + P.ankD*mem.rateP + P.ankI*mem.intP)*bal*bw;
    hip += (P.hipP*eP + P.hipD*mem.rateP + P.hipI*mem.intP)*bal*bw;
    knee += (P.kneeP*eP + P.kneeD*mem.rateP)*bal*bw;

    out += (P.outSameP*eRbal + P.outSameD*mem.rateR)*bal*bw;
    out += sgn*(P.outDiffP*eRbal + P.outDiffD*mem.rateR)*bal*bw;
    roll += (P.ankRollSameP*eRbal + P.ankRollSameD*mem.rateR)*bal*bw;
    roll += sgn*(P.ankRollDiffP*eRbal + P.ankRollDiffD*mem.rateR)*bal*bw;
    twist += sgn*(P.yawP*eY + P.yawD*mem.rateY)*bal*bw;

    knee += P.recKnee*recAmt;
    out += P.recOut*recAmt;
    hip += P.recHip*recAmt;
    ankle += P.recAnkle*recAmt;

    if (dive > 0){
      hip += P.diveHip*dive;
      knee += P.diveKnee*dive;
      ankle += P.diveAnkle*dive;
      out += P.diveOut*dive;
    }

    var b = isLeft ? 1 : 11;
    target[b]   = clamp(hip,LIMLO[b],LIMHI[b]);
    target[b+1] = clamp(out,LIMLO[b+1],LIMHI[b+1]);
    target[b+2] = clamp(twist,LIMLO[b+2],LIMHI[b+2]);
    target[b+3] = clamp(knee,LIMLO[b+3],LIMHI[b+3]);
    target[b+4] = clamp(ankle,LIMLO[b+4],LIMHI[b+4]);
    target[b+5] = clamp(roll,LIMLO[b+5],LIMHI[b+5]);
  }

  var armG = P.armAmp*gA;
  var cosL = Math.cos(2*Math.PI*(mem.phase+P.armPhase));
  var cosR = Math.cos(2*Math.PI*(mem.phase+P.phaseOffset+P.armPhase));
  var armL = P.armFwd0*pose - armG*cosL;
  var armR = P.armFwd0*pose - armG*cosR;

  var armPitch = (P.armPitchP*eP + P.armPitchD*mem.rateP)*bal;
  armL += armPitch;
  armR += armPitch;

  var armRoll = (P.armRollP*eRbal + P.armRollD*mem.rateR)*bal;
  var shBase = P.armOut0*pose + P.recArm*recAmt;
  var shL = shBase + armRoll;
  var shR = shBase - armRoll;
  var elbow = P.elbow0*pose;

  if (dive > 0){
    armL += P.diveArm*dive;
    armR += P.diveArm*dive;
    shL += 0.30*P.diveArm*dive;
    shR += 0.30*P.diveArm*dive;
  }

  target[7]  = clamp(armL,LIMLO[7],LIMHI[7]);
  target[8]  = clamp(shL,LIMLO[8],LIMHI[8]);
  target[9]  = 0;
  target[10] = clamp(elbow,LIMLO[10],LIMHI[10]);
  target[17] = clamp(armR,LIMLO[17],LIMHI[17]);
  target[18] = clamp(shR,LIMLO[18],LIMHI[18]);
  target[19] = 0;
  target[20] = clamp(elbow,LIMLO[20],LIMHI[20]);

  var cmd = [];
  for (j=0;j<21;j++){
    var tv = target[j];
    if (!isFinite(tv)) tv = 0;
    tv = clamp(tv,LIMLO[j],LIMHI[j]);
    var isArm = ((j >= 7 && j <= 10) || (j >= 17 && j <= 20));
    var kpj = isArm ? P.kpArm : P.kp;
    var kvj = isArm ? P.kdArm : P.kd;
    var cv = kpj*(tv-mem.qF[j]) - kvj*mem.dqF[j];
    if (!isFinite(cv)) cv = 0;
    cmd[j] = clamp(cv,-1,1);
  }

  return cmd;
}

function learn(lab){
  var used = 0;
  var all = [];
  var elite = [];
  var standPool = [];
  var gaitPool = [];

  function copy(o){
    var r = {};
    var k;
    if (!o) return r;
    for (k in o){
      if (hasOwn(o,k)) r[k] = o[k];
    }
    return r;
  }
  function fill(par){
    return normP(par);
  }
  function getTrialsLeft(){
    try {
      var x = lab.trialsLeft();
      if (x === undefined || x === null || !isFinite(x)) return 1000;
      return x;
    } catch(e) {
      return 1000;
    }
  }
  function getTimeLeft(){
    try {
      var x = lab.timeLeft();
      if (x === undefined || x === null || !isFinite(x)) return 1000;
      return x;
    } catch(e) {
      return 1000;
    }
  }
  function canTrial(){
    return used < 200 && getTrialsLeft() > 0 && getTimeLeft() > 0.65;
  }
  function randn(){
    var u1 = 0, u2 = 0;
    while (u1 === 0) u1 = Math.random();
    while (u2 === 0) u2 = Math.random();
    return Math.sqrt(-2*Math.log(u1))*Math.cos(2*Math.PI*u2);
  }

  function stats(r){
    var inv = (!r ||
      r.outcome === "invalid" ||
      r.outcome === "error" ||
      r.outcome === "exploit");
    var d = r ? Number(r.distance) : 0;
    if (!isFinite(d)) d = 0;
    var tm = r ? Number(r.time) : 0;
    if (!isFinite(tm)) tm = 0;
    var en = r ? Number(r.energy) : 0;
    if (!isFinite(en)) en = 0;

    var tr = (r && r.trace && r.trace.length) ? r.trace : [];
    var h0 = 1.0;
    var i;
    if (tr.length > 0 && tr[0] && tr[0].length >= 3){
      var hh = Math.abs(num(tr[0][2],0));
      if (hh > 0.12) h0 = hh;
    }

    var rows = [];
    var minR = 1e9;
    var maxRoll = 0;
    var maxPitch = 0;
    var maxSide = 0;
    var last = null;

    for (i=0;i<tr.length;i++){
      var row = tr[i];
      if (!row || row.length < 6) continue;
      var tt = num(row[0],0);
      var dd = num(row[1],0);
      var hh2 = Math.abs(num(row[2],h0));
      var side = Math.abs(num(row[3],0));
      var rr = Math.abs(num(row[4],0));
      var pp = Math.abs(num(row[5],0));
      var ratio = hh2/h0;
      if (ratio < minR) minR = ratio;
      if (side > maxSide) maxSide = side;
      if (rr > maxRoll) maxRoll = rr;
      if (pp > maxPitch) maxPitch = pp;
      rows.push({t:tt,d:dd,h:ratio,side:side,roll:rr,pitch:pp});
      last = row;
    }
    if (minR > 1e8) minR = 1.0;

    var finalR = 1.0;
    var finalSide = 0.0;
    var finalRoll = 0.0;
    var finalPitch = 0.0;
    if (last){
      finalR = Math.abs(num(last[2],h0))/h0;
      finalSide = Math.abs(num(last[3],0));
      finalRoll = Math.abs(num(last[4],0));
      finalPitch = Math.abs(num(last[5],0));
    }

    var fin = (r && r.outcome === "finished") || tm >= 9.55;

    return {
      inv:inv, dist:d, time:tm, fin:fin, energy:Math.abs(en),
      h0:h0, rows:rows, minR:minR,
      maxRoll:maxRoll, maxPitch:maxPitch, maxSide:maxSide,
      finalR:finalR, finalSide:finalSide,
      finalRoll:finalRoll, finalPitch:finalPitch
    };
  }

  function isStable(m){
    return !m.inv && m.fin && m.time > 9.45 &&
      m.minR > 0.54 && m.finalR > 0.60 &&
      m.maxRoll < 0.88 && m.maxPitch < 1.00 &&
      m.maxSide < 1.70 &&
      m.finalRoll < 0.55 && m.finalPitch < 0.72;
  }
  function isVeryStable(m){
    return !m.inv && m.fin && m.time > 9.55 &&
      m.minR > 0.63 && m.finalR > 0.70 &&
      m.maxRoll < 0.68 && m.maxPitch < 0.80 &&
      m.maxSide < 1.20 &&
      m.finalRoll < 0.40 && m.finalPitch < 0.55;
  }
  function scoreM(m){
    if (m.inv) return -1e15;
    var s = 0;
    if (m.fin) s += 1.0e9;
    s += Math.min(10,m.time)*2.0e5;
    s += Math.min(2,m.minR)*2.0e6 + Math.min(2,m.finalR)*1.0e6;
    s -= Math.max(0,m.maxRoll-0.45)*3.0e6;
    s -= Math.max(0,m.maxPitch-0.55)*3.0e6;
    s -= Math.max(0,m.maxSide-0.80)*2.0e6;
    s -= Math.max(0,0.65-m.finalR)*8.0e6;
    if (m.fin){
      s -= Math.max(0,m.finalRoll-0.45)*6.0e6;
      s -= Math.max(0,m.finalPitch-0.55)*6.0e6;
      if (isStable(m)){
        s += 2.0e9 + Math.max(-1,m.dist)*1.0e7;
        if (isVeryStable(m)) s += 3.0e8 + Math.max(-1,m.dist)*3.0e6;
      } else {
        s += Math.max(-1,m.dist)*1.0e6;
      }
    } else {
      s += Math.max(-1,m.dist)*1.0e4;
      s -= (10-m.time)*5.0e4;
    }
    s -= m.energy*0.05;
    return s;
  }

  function evalP(par,tag){
    if (!canTrial()) return null;
    var p = fill(par);
    var r;
    try {
      r = lab.trial(p);
    } catch(e) {
      return null;
    }
    used++;
    var m = stats(r);
    var rec = {p:p,m:m,tag:tag,score:0,stable:false,very:false};
    rec.score = scoreM(m);
    rec.stable = isStable(m);
    rec.very = isVeryStable(m);
    all.push(rec);

    if (p.gaitAmp <= 0.02){
      standPool.push(rec);
      standPool.sort(function(a,b){ return b.score-a.score; });
      if (standPool.length > 60) standPool.length = 60;
    } else {
      gaitPool.push(rec);
      gaitPool.sort(function(a,b){ return b.score-a.score; });
      if (gaitPool.length > 100) gaitPool.length = 100;
    }

    elite.push(rec);
    elite.sort(function(a,b){ return b.score-a.score; });
    if (elite.length > 100) elite.length = 100;
    return rec;
  }

  var SPEC = [
    ["hip0",-0.5,0.8,0.04],
    ["knee0",0.0,0.85,0.03],
    ["ankle0",-0.6,0.4,0.02],
    ["out0",0.0,0.45,0.02],
    ["waist0",-0.5,0.6,0.02],
    ["armFwd0",-0.9,1.1,0.05],
    ["armOut0",0.0,1.0,0.03],
    ["elbow0",0.0,1.3,0.04],
    ["split",-0.35,0.35,0.02],
    ["pitchRef",-0.25,0.35,0.01],
    ["rollRef",-0.12,0.12,0.005],
    ["yawRef",-0.3,0.3,0.01],
    ["poseTime",0.08,1.2,0.03],
    ["kp",0.5,15.0,0.18],
    ["kd",0.0,1.5,0.02],
    ["kpArm",0.3,10.0,0.12],
    ["kdArm",0.0,1.2,0.02],

    ["ankP",-7.0,7.0,0.16],
    ["ankD",-4.0,4.0,0.06],
    ["ankI",-2.0,2.0,0.03],
    ["hipP",-4.0,4.0,0.10],
    ["hipD",-2.5,2.5,0.05],
    ["hipI",-1.5,1.5,0.03],
    ["waistP",-5.0,5.0,0.12],
    ["waistD",-3.0,3.0,0.06],
    ["waistI",-2.0,2.0,0.03],
    ["kneeP",-3.0,3.0,0.06],
    ["kneeD",-2.0,2.0,0.04],
    ["outSameP",-5.0,5.0,0.12],
    ["outSameD",-3.0,3.0,0.06],
    ["outDiffP",-5.0,5.0,0.12],
    ["outDiffD",-3.0,3.0,0.06],
    ["ankRollSameP",-6.0,6.0,0.14],
    ["ankRollSameD",-4.0,4.0,0.06],
    ["ankRollDiffP",-5.0,5.0,0.12],
    ["ankRollDiffD",-3.0,3.0,0.06],
    ["yawP",-2.5,2.5,0.06],
    ["yawD",-2.0,2.0,0.05],
    ["armPitchP",-2.5,2.5,0.06],
    ["armPitchD",-2.0,2.0,0.05],
    ["armRollP",-2.5,2.5,0.06],
    ["armRollD",-2.0,2.0,0.05],

    ["gaitAmp",0.0,1.5,0.04],
    ["period",0.22,2.7,0.05],
    ["stanceFrac",0.32,0.90,0.02],
    ["phaseOffset",0.0,1.0,0.03],
    ["startTime",0.0,2.5,0.05],
    ["ramp",0.05,2.5,0.05],
    ["startPhase",0.0,1.0,0.03],
    ["hipAmp",-0.2,1.4,0.05],
    ["kneeSwing",-0.1,2.0,0.06],
    ["kneeLand",-0.2,0.9,0.03],
    ["kneeStance",-0.3,0.6,0.02],
    ["kneePush",-0.3,0.7,0.03],
    ["ankleSwing",-0.6,0.9,0.04],
    ["ankleStance",-0.6,0.6,0.03],
    ["anklePush",-0.6,0.6,0.03],
    ["outSwing",-0.4,0.6,0.02],
    ["outStance",-0.4,0.4,0.02],
    ["armAmp",0.0,1.5,0.04],
    ["armPhase",-3.2,3.2,0.10],
    ["latAmp",-0.25,0.25,0.01],
    ["latPhase",-3.2,3.2,0.10],
    ["loadP",-0.5,0.5,0.03],
    ["waitGain",0.0,1.2,0.04],
    ["phaseP",-2.5,2.5,0.05],
    ["phaseD",-1.5,1.5,0.04],

    ["terrainKnee",-2.5,5.0,0.10],
    ["terrainHip",-2.5,4.0,0.06],
    ["terrainAnkle",-2.5,4.0,0.06],
    ["terrainDownKnee",-4.0,4.0,0.08],
    ["terrainDownHip",-2.5,2.5,0.05],
    ["terrainDownAnkle",-2.5,2.5,0.05],
    ["stumbleKnee",-1.2,1.8,0.05],
    ["stumbleHip",-1.0,1.2,0.04],
    ["stumbleAnkle",-1.0,1.2,0.04],
    ["contactThresh",0.02,0.65,0.01],

    ["safeP",0.15,1.30,0.03],
    ["safeR",0.15,1.30,0.03],
    ["safeGain",0.0,12.0,0.10],
    ["recDamp",0.0,1.25,0.03],
    ["recKnee",-0.1,1.0,0.03],
    ["recOut",-0.1,0.7,0.02],
    ["recHip",-0.6,0.6,0.03],
    ["recAnkle",-0.6,0.6,0.03],
    ["recArm",0.0,1.1,0.03],
    ["airDamp",0.0,1.2,0.03],

    ["stopTime",5.0,999.0,2.0],
    ["stopRamp",0.10,2.0,0.06],
    ["diveRamp",0.08,1.0,0.04],
    ["diveHip",-1.2,1.6,0.10],
    ["diveKnee",-1.0,1.0,0.08],
    ["diveAnkle",-1.2,1.2,0.08],
    ["diveWaist",-0.8,1.6,0.08],
    ["diveOut",-0.5,0.5,0.04],
    ["diveArm",-1.0,2.0,0.08],
    ["diveBal",0.0,1.4,0.06]
  ];

  var SPEC_MAP = {};
  var si;
  for (si=0; si<SPEC.length; si++) SPEC_MAP[SPEC[si][0]] = SPEC[si];

  function mutate(base,scale,focus){
    var o = fill(base);
    var n = 1 + Math.floor(Math.random()*4);
    var q;
    for (q=0;q<n;q++){
      var sp;
      if (focus && focus.length && Math.random() < 0.76){
        sp = SPEC_MAP[focus[Math.floor(Math.random()*focus.length)]];
      } else {
        sp = SPEC[Math.floor(Math.random()*SPEC.length)];
      }
      if (!sp) continue;
      var key = sp[0];
      var v = num(o[key],num(DEF[key],0));
      v += randn()*sp[3]*scale*(0.55+0.90*Math.random());
      if (Math.random() < 0.022) v = sp[1] + Math.random()*(sp[2]-sp[1]);
      o[key] = clamp(v,sp[1],sp[2]);
    }
    return fill(o);
  }

  var standFocus = [
    "hip0","knee0","ankle0","out0","waist0","split","pitchRef","poseTime",
    "kp","kd","ankP","ankD","ankI","hipP","hipD","hipI","waistP","waistD","waistI",
    "kneeP","kneeD","outSameP","outSameD","outDiffP","outDiffD",
    "ankRollSameP","ankRollSameD","ankRollDiffP","ankRollDiffD",
    "safeP","safeR","safeGain","recKnee","recOut","recHip","recAnkle","recArm",
    "armOut0","armFwd0","elbow0","airDamp"
  ];
  var gaitFocus = [
    "gaitAmp","period","stanceFrac","phaseOffset","startTime","ramp","startPhase",
    "hipAmp","kneeSwing","kneeLand","kneeStance","kneePush",
    "ankleSwing","ankleStance","anklePush","outSwing","outStance",
    "armAmp","armPhase","latAmp","latPhase","loadP","waitGain","phaseP","phaseD",
    "hip0","knee0","ankle0","out0","pitchRef","stopTime","stopRamp"
  ];
  var balanceFocus = [
    "ankP","ankD","ankI","hipP","hipD","hipI","waistP","waistD","waistI",
    "kneeP","kneeD","outSameP","outSameD","outDiffP","outDiffD",
    "ankRollSameP","ankRollSameD","ankRollDiffP","ankRollDiffD",
    "yawP","yawD","armPitchP","armPitchD","armRollP","armRollD",
    "safeP","safeR","safeGain","recDamp","recKnee","recOut","recHip",
    "recAnkle","recArm","airDamp","contactThresh","kp","kd","kpArm","kdArm"
  ];
  var terrainFocus = [
    "terrainKnee","terrainHip","terrainAnkle",
    "terrainDownKnee","terrainDownHip","terrainDownAnkle",
    "stumbleKnee","stumbleHip","stumbleAnkle",
    "contactThresh","safeP","safeR","safeGain","recDamp","waitGain"
  ];

  var baseStand = fill(DEF);
  baseStand.gaitAmp = 0;
  baseStand.latAmp = 0;
  baseStand.stopTime = 999;
  baseStand.diveStart = 999;

  var poses = [
    {knee0:0.05,hip0:0.00,ankle0:0.00,out0:0.08},
    {knee0:0.18,hip0:0.03,ankle0:-0.03,out0:0.15},
    {knee0:0.32,hip0:0.06,ankle0:-0.06,out0:0.22},
    {knee0:0.23,hip0:0.10,ankle0:-0.08,out0:0.18}
  ];

  var gainSets = [
    {},
    {ankP:-1.8,ankD:-0.28,hipP:0.45,hipD:0.08,waistP:-0.45,waistD:-0.08,
     outDiffP:-0.65,outDiffD:-0.10,ankRollSameP:-0.55,ankRollSameD:-0.08},
    {ankP:-0.9,ankD:-0.14,hipP:0.22,hipD:0.04,waistP:-0.22,waistD:-0.04,
     outDiffP:-0.35,outDiffD:-0.05,ankRollSameP:-0.30,ankRollSameD:-0.04},
    {ankP:-3.0,ankD:-0.45,hipP:0.80,hipD:0.14,waistP:-0.80,waistD:-0.14,
     outDiffP:-1.00,outDiffD:-0.16,ankRollSameP:-0.85,ankRollSameD:-0.12},
    {ankP:1.8,ankD:0.28,hipP:-0.45,hipD:-0.08,waistP:0.45,waistD:0.08,
     outDiffP:0.65,outDiffD:0.10,ankRollSameP:0.55,ankRollSameD:0.08},
    {ankP:-1.8,ankD:-0.28,hipP:0.45,hipD:0.08,waistP:-0.45,waistD:-0.08,
     outDiffP:0.65,outDiffD:0.10,ankRollSameP:0.55,ankRollSameD:0.08},
    {ankP:-1.8,ankD:-0.28,hipP:0.45,hipD:0.08,waistP:-0.45,waistD:-0.08,
     outDiffP:0.0,outDiffD:0.0,ankRollSameP:0.0,ankRollSameD:0.0},
    {ankP:-1.8,ankD:-0.28,hipP:0.45,hipD:0.08,waistP:-0.45,waistD:-0.08,
     outDiffP:-0.35,outDiffD:-0.05,ankRollDiffP:0.75,ankRollDiffD:0.10}
  ];

  var pi, gi, k;
  for (pi=0; pi<poses.length && canTrial(); pi++){
    for (gi=0; gi<gainSets.length && canTrial(); gi++){
      var st = copy(baseStand);
      for (k in poses[pi]) if (hasOwn(poses[pi],k)) st[k] = poses[pi][k];
      for (k in gainSets[gi]) if (hasOwn(gainSets[gi],k)) st[k] = gainSets[gi][k];
      st.gaitAmp = 0;
      st.latAmp = 0;
      st.stopTime = 999;
      st.diveStart = 999;
      evalP(st,"standseed");
    }
  }

  var standScale = 0.90;
  var standNo = 0;
  var bestStandScore = -1e18;
  if (standPool.length > 0) bestStandScore = standPool[0].score;

  var standLimit = 72;
  while (used < standLimit && canTrial()){
    var sParent;
    if (standPool.length > 0){
      var idxs = Math.floor(Math.random()*Math.min(standPool.length,10));
      if (Math.random() < 0.32) idxs = 0;
      sParent = standPool[Math.min(idxs,standPool.length-1)].p;
    } else if (elite.length > 0){
      sParent = elite[0].p;
    } else {
      sParent = baseStand;
    }
    var sChild = mutate(sParent,standScale,standFocus);
    sChild.gaitAmp = 0;
    sChild.latAmp = 0;
    sChild.stopTime = 999;
    sChild.diveStart = 999;
    var sRec = evalP(sChild,"standevo");
    if (sRec){
      if (sRec.score > bestStandScore + 1e-9){
        bestStandScore = sRec.score;
        standNo = 0;
        standScale = Math.max(0.25,standScale*0.90);
      } else {
        standNo++;
        standScale = Math.min(1.55,standScale*1.005);
      }
      if (standNo > 10){
        standNo = 0;
        standScale = Math.min(1.85,standScale*1.28);
        if (canTrial()){
          var rs = mutate(baseStand,1.15,standFocus);
          rs.gaitAmp = 0;
          rs.latAmp = 0;
          rs.stopTime = 999;
          rs.diveStart = 999;
          evalP(rs,"standrestart");
        }
      }
    }
  }

  var baseLoc;
  if (standPool.length > 0) baseLoc = copy(standPool[0].p);
  else if (elite.length > 0) baseLoc = copy(elite[0].p);
  else baseLoc = copy(baseStand);

  var amps = [0.045,0.075,0.110,0.160,0.230,0.320];
  var periods = [0.85,1.00,1.20,1.45,1.70];
  var stances = [0.58,0.64,0.70,0.76];
  var hips = [0.25,0.35,0.48,0.60];
  var kneesw = [0.40,0.60,0.82,1.05];
  var lats = [0.00,0.025,0.050,0.080];

  var ii;
  for (ii=0; ii<30 && canTrial(); ii++){
    var gp = copy(baseLoc);
    gp.gaitAmp = amps[ii%amps.length];
    gp.period = periods[(ii+1)%periods.length];
    gp.stanceFrac = stances[(ii+2)%stances.length];
    gp.phaseOffset = 0.50;
    gp.startTime = 0.55 + 0.10*(ii%3);
    gp.ramp = 0.70 + 0.06*(ii%4);
    gp.startPhase = 0.0;
    gp.hipAmp = hips[(ii>>1)%hips.length];
    gp.kneeSwing = kneesw[(ii+1)%kneesw.length];
    gp.kneeLand = 0.035 + 0.018*(ii%4);
    gp.kneeStance = 0.02;
    gp.kneePush = 0.025;
    gp.ankleSwing = 0.05 + 0.025*(ii%4);
    gp.ankleStance = 0.04;
    gp.anklePush = 0.035 + 0.012*(ii%3);
    gp.outSwing = 0.010 + 0.008*(ii%3);
    gp.outStance = 0.0;
    gp.latAmp = lats[(ii>>2)%lats.length];
    gp.latPhase = 0.0;
    gp.loadP = 0.03 + 0.02*(ii%3);
    gp.armAmp = 0.10 + 0.03*(ii%4);
    gp.stopTime = 999;
    gp.diveStart = 999;
    gp.safeGain = Math.max(2.0,gp.safeGain);
    gp.recDamp = 0.75;
    evalP(gp,"gaitseed");
  }

  var gaitScale = 0.85;
  var gaitNo = 0;
  var bestGaitScore = -1e18;
  if (gaitPool.length > 0) bestGaitScore = gaitPool[0].score;

  var gaitLimit = 166;
  while (used < gaitLimit && canTrial()){
    var gParent;
    var rr = Math.random();
    if (gaitPool.length > 0 && rr < 0.82){
      var idxg = Math.floor(Math.random()*Math.min(gaitPool.length,16));
      if (Math.random() < 0.30) idxg = 0;
      gParent = gaitPool[Math.min(idxg,gaitPool.length-1)].p;
    } else if (standPool.length > 0 && rr < 0.92){
      gParent = standPool[Math.floor(Math.random()*Math.min(standPool.length,8))].p;
    } else if (elite.length > 0){
      gParent = elite[Math.floor(Math.random()*Math.min(elite.length,8))].p;
    } else {
      gParent = baseLoc;
    }

    var focus;
    var rf = Math.random();
    if (rf < 0.54) focus = gaitFocus;
    else if (rf < 0.84) focus = balanceFocus;
    else focus = terrainFocus;

    var gChild = mutate(gParent,gaitScale,focus);
    gChild.diveStart = 999;
    if (gChild.gaitAmp < 0.025){
      if (Math.random() < 0.78) gChild.gaitAmp = 0.025 + Math.random()*0.35;
      else gChild.gaitAmp = 0;
    }

    if (Math.random() < 0.045){
      gChild.gaitAmp = 0.04 + Math.random()*0.60;
      gChild.period = 0.45 + Math.random()*1.30;
      gChild.stanceFrac = 0.52 + Math.random()*0.28;
      gChild.phaseOffset = 0.50;
      gChild.startTime = 0.45 + Math.random()*0.70;
      gChild.hipAmp = 0.20 + Math.random()*0.60;
      gChild.kneeSwing = 0.35 + Math.random()*0.80;
      gChild.ankleSwing = 0.04 + Math.random()*0.12;
      gChild.latAmp = -0.05 + Math.random()*0.15;
      gChild.latPhase = Math.random()*6.28-3.14;
    }

    var grec = evalP(gChild,"gaitevo");
    if (grec){
      if (grec.score > bestGaitScore + 1e-9){
        bestGaitScore = grec.score;
        gaitNo = 0;
        gaitScale = Math.max(0.22,gaitScale*0.90);
      } else {
        gaitNo++;
        gaitScale = Math.min(1.70,gaitScale*1.005);
      }
      if (gaitNo > 12){
        gaitNo = 0;
        gaitScale = Math.min(1.90,gaitScale*1.24);
        if (canTrial()){
          var kick = mutate(baseLoc,1.20,gaitFocus);
          kick.gaitAmp = 0.06 + Math.random()*0.55;
          kick.period = 0.50 + Math.random()*1.25;
          kick.stanceFrac = 0.54 + Math.random()*0.24;
          kick.phaseOffset = 0.50;
          kick.startTime = 0.45 + Math.random()*0.60;
          kick.diveStart = 999;
          evalP(kick,"kick");
        }
      }
    }
  }

  function distanceAt(m,T){
    if (!m || m.inv) return -1e18;
    if (!m.rows || m.rows.length === 0) return m.dist;
    var d = 0;
    var i;
    for (i=0;i<m.rows.length;i++){
      if (m.rows[i].t <= T + 1e-9) d = m.rows[i].d;
      else break;
    }
    return d;
  }

  var gaitRecs = [];
  var i2;
  for (i2=0;i2<all.length;i2++){
    if (all[i2].p.gaitAmp > 0.025 && all[i2].m.fin && !all[i2].m.inv){
      gaitRecs.push(all[i2]);
    }
  }
  gaitRecs.sort(function(a,b){ return b.m.dist-a.m.dist; });

  var valCount = 0;
  var vi;
  for (vi=0; vi<Math.min(4,gaitRecs.length) && valCount<10; vi++){
    if (!canTrial()) break;
    var cand0 = gaitRecs[vi];

    var v1 = copy(cand0.p);
    v1.gaitAmp *= 0.82;
    if (v1.gaitAmp < 0.025) v1.gaitAmp = 0.025;
    v1.period *= 1.04;
    v1.safeGain = Math.min(12.0,v1.safeGain*1.12);
    v1.recDamp = Math.min(1.2,v1.recDamp*1.08);
    v1.stopTime = 999;
    v1.diveStart = 999;
    evalP(v1,"validate82");
    valCount++;

    if (canTrial() && valCount<10){
      var v2 = copy(cand0.p);
      v2.gaitAmp *= 0.66;
      if (v2.gaitAmp < 0.025) v2.gaitAmp = 0.025;
      v2.period *= 1.08;
      v2.safeGain = Math.min(12.0,v2.safeGain*1.22);
      v2.recDamp = Math.min(1.2,v2.recDamp*1.14);
      v2.stopTime = 999;
      v2.diveStart = 999;
      evalP(v2,"validate66");
      valCount++;
    }
  }

  var stableStand = null;
  for (i2=0;i2<standPool.length;i2++){
    if (standPool[i2].p.gaitAmp <= 0.02 && isStable(standPool[i2].m) &&
        standPool[i2].m.minR > 0.58 && standPool[i2].m.maxRoll < 0.65 &&
        standPool[i2].m.maxPitch < 0.70){
      stableStand = standPool[i2];
      break;
    }
  }
  if (!stableStand){
    for (i2=0;i2<all.length;i2++){
      var rss = all[i2];
      if (rss.p.gaitAmp <= 0.02 && isStable(rss.m)){
        stableStand = rss;
        break;
      }
    }
  }

  var prelim = null;
  var prelimScore = -1e18;
  var bestStableGait = null;
  var bestStableGaitQ = -1e18;

  for (i2=0;i2<all.length;i2++){
    var rec = all[i2];
    if (rec.p.gaitAmp > 0.025 && rec.stable){
      var q = rec.m.dist +
        0.35*rec.m.minR + 0.20*rec.m.finalR -
        0.35*rec.m.maxPitch - 0.35*rec.m.maxRoll -
        0.15*rec.m.maxSide - 0.20*rec.p.gaitAmp;
      if (rec.very) q += 0.8 + 0.10*rec.m.dist;
      if (q > bestStableGaitQ){
        bestStableGaitQ = q;
        bestStableGait = rec;
      }
    }
  }

  if (bestStableGait){
    prelim = bestStableGait;
  } else {
    var bestFin = null;
    var bestFinD = -1e18;
    for (i2=0;i2<all.length;i2++){
      rec = all[i2];
      if (rec.p.gaitAmp > 0.025 && rec.m.fin && rec.m.minR > 0.48 &&
          rec.m.maxRoll < 1.05 && rec.m.maxPitch < 1.20 && rec.m.maxSide < 2.0){
        var val = rec.m.dist - 0.4*rec.m.maxPitch - 0.4*rec.m.maxRoll - 0.15*rec.m.maxSide;
        if (val > bestFinD){ bestFinD = val; bestFin = rec; }
      }
    }
    if (bestFin) prelim = bestFin;
    else if (stableStand) prelim = stableStand;
    else if (standPool.length > 0) prelim = standPool[0];
    else if (elite.length > 0) prelim = elite[0];
    else prelim = {p:baseLoc,m:stats(null)};
  }

  var finalBaseRec = prelim;
  var finalP = copy(finalBaseRec.p);

  var chosenDive = null;
  var bestDiveGain = 0.02;

  if (canTrial()){
    var baseDist = finalBaseRec.m ? finalBaseRec.m.dist : 0;
    if (!isFinite(baseDist)) baseDist = 0;
    var diveVariants = [
      {hip:0.45,knee:-0.05,ankle:0.20,waist:0.55,out:0.00,arm:0.45,bal:0.75,ramp:0.35},
      {hip:0.25,knee:0.20,ankle:0.30,waist:0.40,out:0.02,arm:0.30,bal:0.60,ramp:0.45},
      {hip:0.75,knee:-0.25,ankle:-0.20,waist:0.80,out:0.00,arm:0.75,bal:1.00,ramp:0.35},
      {hip:-0.15,knee:0.08,ankle:0.40,waist:0.45,out:0.00,arm:0.35,bal:0.65,ramp:0.45},
      {hip:0.55,knee:0.05,ankle:-0.35,waist:0.70,out:0.00,arm:0.55,bal:0.85,ramp:0.40},
      {hip:0.35,knee:-0.15,ankle:0.00,waist:0.60,out:0.03,arm:0.60,bal:0.90,ramp:0.30},
      {hip:0.10,knee:0.30,ankle:0.10,waist:0.30,out:0.00,arm:0.20,bal:0.50,ramp:0.50},
      {hip:0.60,knee:-0.10,ankle:0.45,waist:0.65,out:0.00,arm:0.50,bal:0.80,ramp:0.40}
    ];
    var di;
    for (di=0; di<diveVariants.length && canTrial(); di++){
      var dv = diveVariants[di];
      var dp = copy(finalP);
      dp.diveStart = 7.6;
      dp.diveRamp = dv.ramp;
      dp.diveHip = dv.hip;
      dp.diveKnee = dv.knee;
      dp.diveAnkle = dv.ankle;
      dp.diveWaist = dv.waist;
      dp.diveOut = dv.out;
      dp.diveArm = dv.arm;
      dp.diveBal = dv.bal;
      dp.stopTime = Math.min(dp.stopTime,999);
      var drec = evalP(dp,"dive");
      if (drec && !drec.m.inv){
        var gain = drec.m.dist - baseDist;
        if (gain > bestDiveGain){
          bestDiveGain = gain;
          chosenDive = drec;
        }
      }
    }
  }

  if (chosenDive && bestDiveGain > 0.035){
    finalP = copy(chosenDive.p);
    finalP.diveStart = 17.6;
    finalP.diveRamp = chosenDive.p.diveRamp;
    finalP.diveHip = chosenDive.p.diveHip;
    finalP.diveKnee = chosenDive.p.diveKnee;
    finalP.diveAnkle = chosenDive.p.diveAnkle;
    finalP.diveWaist = chosenDive.p.diveWaist;
    finalP.diveOut = chosenDive.p.diveOut;
    finalP.diveArm = chosenDive.p.diveArm;
    finalP.diveBal = chosenDive.p.diveBal;
  } else {
    finalP.diveStart = 999.0;
  }

  if (finalBaseRec && finalBaseRec.stable && !finalBaseRec.very && stableStand && finalP.gaitAmp > 0.025){
    if (finalP.stopTime > 12.0){
      finalP.stopTime = 9.6;
      finalP.stopRamp = 1.0;
    }
  }

  return fill(finalP);
}

function policy(obs, params, mem) {
  function safeNum(x) {
    return (typeof x === 'number' && isFinite(x)) ? x : 0;
  }

  // Fallback used only if the main controller throws: drive every joint to its straight pose.
  function fallbackStand(o) {
    var res = [];
    var jq = o.joints || [];
    var jv = o.speeds || [];
    for (var i = 0; i < 21; i++) {
      var u = 2.0 * (0 - safeNum(jq[i])) - 0.1 * safeNum(jv[i]);
      if (!(u === u)) u = 0;
      if (u > 1) u = 1;
      if (u < -1) u = -1;
      res.push(u);
    }
    return res;
  }

  function controlStep(o, prm, m) {
    var DEF = {
      f: 1.0, H0: 0.1, AH: 0.3, K0: 0.25, AK: 0.5, AP: 0.2, AL: 0.05,
      P0: 0.0, psi: -1.0, AS: 0.3, S0: 0.1, SO0: 0.15, E0: 0.6,
      Ka: 1.5, Kh: 0.8, Kra: 1.0, Kho: 0.5, Kdp: 0.08, Kdr: 0.08,
      W0: 0.05, HO0: 0.05, KP: 5.0, KD: 0.1, Tramp: 1.0, Kg: 2.5,
      sp: 1, sr: 1
    };
    var P = {};
    for (var key in DEF) {
      if (Object.prototype.hasOwnProperty.call(DEF, key)) {
        var pv = prm[key];
