      [-0.173, 2.161], [-0.753, 0.693], [-0.05, 2.185], [-0.443, 1.787],
      [-0.278, 0.681], [-0.573, 0.736], [-0.05, 2.2], [-0.892, 0.462],
      [-0.354, 0.349], [-0.965, 2.641], [-0.23, 2.116], [-0.771, 0.805],
      [-0.05, 2.404]
