    ['f', 0.6, 2.0, 1.0],
    ['H0', -0.3, 0.5, 0.1],
    ['AH', 0.05, 0.6, 0.3],
    ['AK', 0.1, 1.2, 0.5],
    ['K0', 0.0, 0.6, 0.25],
    ['AP', 0.0, 0.5, 0.2],
    ['AL', 0.0, 0.2, 0.05],
    ['Ka', 0.0, 3.0, 1.5],
    ['Kh', 0.0, 2.0, 0.8],
    ['Kra', 0.0, 3.0, 1.0],
    ['Kho', 0.0, 2.0, 0.5],
    ['KP', 1.5, 10.0, 5.0],
    ['KD', 0.0, 0.4, 0.1],
    ['AS', 0.0, 0.8, 0.3],
    ['W0', -0.2, 0.3, 0.05]
