          bestC = ch;
        }
      }
      if (bestC !== null) {
        if (bestJ > mJ) {
          m = bestC.u.slice();
          mJ = bestJ;
          sigma = Math.min(0.3, sigma * 1.25);
        } else {
          sigma = Math.max(0.02, sigma * 0.85);
        }
      }
    }
    return true;
  }

  var defU = [];
  for (var i0 = 0; i0 < D; i0++) {
    defU.push((SPEC[i0][3] - SPEC[i0][1]) / (SPEC[i0][2] - SPEC[i0][1]));
