    var combos = [[1, 1], [1, -1], [-1, 1], [-1, -1]];
    for (var ci = 0; ci < combos.length; ci++) {
      if (stop) break;
      var sp = combos[ci][0];
      var sr = combos[ci][1];
      var c0 = { u: defU.slice(), sp: sp, sr: sr, Js: [] };
      cands.push(c0);
      if (!evalCand(c0)) break;
      for (var rr = 0; rr < 4; rr++) {
        var uR = [];
        for (var j = 0; j < D; j++) uR.push(clamp01(defU[j] + 0.3 * gauss()));
        var cR = { u: uR, sp: sp, sr: sr, Js: [] };
        cands.push(cR);
        if (!evalCand(cR)) break;
      }
    }

    // Phase B: evolution strategy from the three best seeds.
    var seeds = ranked().slice(0, 3);
    for (var si = 0; si < seeds.length && !stop; si++) {
      var avail = trialsLeft() - RESERVE - 4;
      var share = Math.floor(avail / (seeds.length - si));
      if (share < 4) break;
      es(seeds[si], share, RESERVE);
    }

    // Phase C: re-test the leaders to average out the sensor noise.
    var fin = ranked().slice(0, 4);
