          stop = true;
          break;
        }
        if (!evalCand(fin[fi])) break;
      }
    }
  } catch (err) {
    // Keep whatever has been evaluated so far.
  }

  var rk = ranked();
  if (rk.length > 0) return toParams(rk[0]);
  return toParams({ u: defU, sp: 1, sr: 1, Js: [] });
}

