  }

  try {
    var seedRecs = [];
    for (si = 0; si < SEEDS.length && !stopped; si++) {
      var rs = evalU(encode(merged(SEEDS[si])));
      if (rs !== null) seedRecs.push(rs);
    }
    var mean = null;
    if (seedRecs.length > 0) {
      var bestSeed = seedRecs[0];
      for (si = 1; si < seedRecs.length; si++) {
        if (seedRecs[si].scores[0] > bestSeed.scores[0]) bestSeed = seedRecs[si];
      }
      mean = bestSeed.u.slice();
    }
    var sigma = 0.12;
    var genBest = -1e9;
    var guard = 0;
    while (mean !== null && !stopped && trialsLeft() > RESERVE && guard < MAX_GEN) {
      guard += 1;
      var kids = [];
      for (k = 0; k < LAM && !stopped && trialsLeft() > RESERVE; k++) {
        var x = [];
        for (a = 0; a < nd; a++) x.push(clamp01(mean[a] + sigma * randn()));
        var rc = evalU(x);
        if (rc === null) break;
        kids.push(rc);
      }
      if (kids.length === 0) break;
      kids.sort(function (p1, p2) { return p2.scores[0] - p1.scores[0]; });
      var nm = [];
      for (c = 0; c < nd; c++) nm.push(0);
      var ws = 0;
      for (j = 0; j < MU && j < kids.length; j++) {
        ws += WTS[j];
        for (c = 0; c < nd; c++) nm[c] += WTS[j] * kids[j].u[c];
      }
      for (c = 0; c < nd; c++) nm[c] = nm[c] / ws;
      mean = nm;
      if (kids[0].scores[0] > genBest) { genBest = kids[0].scores[0]; sigma *= 1.1; }
      else sigma *= 0.9;
      sigma = clampN(sigma, 0.03, 0.25);
    }
    var pool = recs.slice();
    pool.sort(function (q1, q2) { return meanScore(q2) - meanScore(q1); });
    var top = pool.slice(0, 4);
    for (rep = 0; rep < 2 && !stopped; rep++) {
      for (ti = 0; ti < top.length && !stopped; ti++) {
        var rr = runTrial(top[ti].p);
        if (rr === null) break;
        top[ti].scores.push(scoreTrial(rr));
      }
    }
  } catch (err) {
    // keep whatever has been evaluated so far
  }

  var pickFrom = [];
  for (q = 0; q < recs.length; q++) {
    if (recs[q].scores.length >= 2) pickFrom.push(recs[q]);
  }
  if (pickFrom.length === 0) pickFrom = recs.slice();
  var best = null;
  var bm = -1e18;
  for (q = 0; q < pickFrom.length; q++) {
    var mv = meanScore(pickFrom[q]);
    if (best === null || mv > bm) { best = pickFrom[q]; bm = mv; }
  }
  if (best !== null) return best.p;
  return decode(encode(merged({})));
}
